When _reCalFs is called from dctStake, maxEarning may be stale. This is because if the poolOwner has unshared earnings that have not yet been counted into maxEarning, then the actual maxEarning will be larger than the current one.  
```solidity
function shareCommission(
    address account_
)
public
{
    uint amount = balanceOf(account_) - _sharedA[account_];
    if (amount == 0) {
        return;
    }
    address sponsor;
    uint sAmount;
    (sponsor, sAmount) =
        _profileC.getSponsorPart(account_, amount);
    if (sAmount > 0) {
        _transfer(account_, sponsor, sAmount);
        emit ShareCommission(account_, sponsor, sAmount);
    }
    _sharedA[account_] = balanceOf(account_);
    if (_sharedA[account_] > _maxEarningOf[account_]) {
        _updateMaxEarning(account_, _sharedA[account_]);
    }
}
```

The FlashProtocol contract provides a public stake() function for users to stake principal tokens and mint the corresponding amount of fToken to the users. The users-staked funds are transferred to the FlashStrategy to earn yields. The fToken can be burned by the stakers to claim yields earned by the FlashStrategy. To facilitate the yield claiming for users, the FlashProtocol contract also provides an external flashStake() function in which the acts of staking, minting fToken and burning all fToken are done in one transaction.  
In the following, we examine the FlashProtocol::flashStake() routine that is designed to provide the staker with instant upfront yield within one transaction. We notice the actual burn fToken and claim yield operation IFlashStrategy(_strategyAddress).burnFToken() essentially specifies no restriction on possible slippage and is therefore vulnerable to possible front-running attacks, resulting in a smaller return (line 293). Note the way to use the quotedReturn parameter is invalid as it is eventually computed from IFlashStrategy(_strategyAddress).quoteBurnFToken() (line 289). In other words, the IFlashStrategy(_strategyAddress).quoteBurnFToken() output guarantees tokensOwed=_minimumReturned  
```solidity
function flashStake(
    address _strategyAddress,
    uint256 _tokenAmount,
    uint256 _stakeDuration,
    address _yieldTo,
    bool _mintNFT
) external nonReentrant {
    // Stake
    uint256 fTokensMinted = stake(_strategyAddress, _tokenAmount, _stakeDuration, _yieldTo, _mintNFT).fTokensToUser;
    IERC20C fToken = IERC20C(strategies[_strategyAddress].fTokenAddress);
    fToken.transferFrom(msg.sender, address(this), fTokensMinted);
    // Quote, approve, burn
    uint256 quotedReturn = IFlashStrategy(_strategyAddress).quoteBurnFToken(fTokensMinted);
    // Approve and send yield to specified address
    fToken.approve(_strategyAddress, fTokensMinted);
    IFlashStrategy(_strategyAddress).burnFToken(fTokensMinted, quotedReturn, _yieldTo);
}
```

In the FireBirdRouter contract, we observe the _swapSingleSupportFeeOnTransferTokens() function is used to swap the exact amount of tokenIn to tokenOut. To elaborate, we show below the related code snippet. In the function, the FireBirdFormula::getFactoryReserveAndWeights() function is called (line 460) to acquire the current state of the pool which is a FireBirdPair instance that stores two different tokens address and the related info, including reserve0, reserve1, tokenWeight0, swapFee, and so on. These parameters of the pool will be used by FireBirdFormula::getAmountOut() (line 462) to calculate the amount of tokenOut swapped with the exact amount of tokenIn.  
In the FireBirdFormula::getFactoryReserveAndWeights() function, we notice if the third input argument tokenA is not equal to the token0 address in the pool specified by the second input argument pair, tokenA will be treated as token1 and the function will return the corresponding state of the pool. If tokenA is neither equal to token0, nor equal to token1, the function will return incorrect values, which may introduce unexpected behavior for those functions call it. We may need to validate tokenA is either equal to token0 or equal to token1 at the beginning of the function.  
```solidity
function _swapSingleSupportFeeOnTransferTokens(address tokenIn, address tokenOut, address pool, uint swapAmount, uint limitReturnAmount) internal returns(uint tokenAmountOut) {
    TransferHelper.safeTransfer(tokenIn, pool, swapAmount);
    uint amountOutput;
    (, uint reserveInput, uint reserveOutput, uint32 tokenWeightInput, uint32 tokenWeightOutput, uint32 swapFee) = IFireBirdFormula(formula).getFactoryReserveAndWeights(factory, pool, tokenIn);
    uint amountInput = IERC20(tokenIn).balanceOf(pool).sub(reserveInput);
    amountOutput = IFireBirdFormula(formula).getAmountOut(amountInput, reserveInput, reserveOutput, tokenWeightInput, tokenWeightOutput, swapFee);
    uint balanceBefore = IERC20(tokenOut).balanceOf(address(this));
    (uint amount0Out, uint amount1Out) = tokenIn == IFireBirdPair(pool).token0() ? (uint(0), amountOutput) : (amountOutput, uint(0));
    IFireBirdPair(pool).swap(amount0Out, amount1Out, address(this), new bytes(0));
    emit Exchange(pool, amountOutput, tokenOut);
    tokenAmountOut = IERC20(tokenOut).balanceOf(address(this)).sub(balanceBefore);
    require(tokenAmountOut >= limitReturnAmount, "Router: INSUFFICIENT_OUTPUT_AMOUNT");
}

function getFactoryReserveAndWeights(address factory, address pair, address tokenA)
    public
    override
    view
    returns (
        address tokenB,
        uint reserveA,
        uint reserveB,
        uint32 tokenWeightA,
        uint32 tokenWeightB,
        uint32 swapFee
    )
{
    address token0 = IFireBirdPair(pair).token0();
    (uint reserve0, uint reserve1,) = IFireBirdPair(pair).getReserves();
    uint32 tokenWeight0;
    uint32 tokenWeight1;
    (tokenWeight0, tokenWeight1, swapFee) = getFactoryWeightsAndSwapFee(factory, pair);
    if (tokenA == token0) {
        (tokenB, reserveA, reserveB, tokenWeightA, tokenWeightB) = (IFireBirdPair(pair).token1(), reserve0, reserve1, tokenWeight0, tokenWeight1);
    } else {
        (tokenB, reserveA, reserveB, tokenWeightA, tokenWeightB) = (token0, reserve1, reserve0, tokenWeight1, tokenWeight0);
    }
}
```
Note a number of functions can be similarly improved, including FireBirdFormula::getReserveAndWeights(), FireBirdFormula::getReserves() and FireBirdFormula::getOtherToken().

When User calls the Vault::deposit(...) function, his assets are transferred to the Vault and requestId is generated for the deposit that will be used to increase his collateral:  
```solidity
function deposit(address _tokenAddress, bytes32 _subaccount, uint256 _amount)
external
payable
nonReentrant
onlyAcceptedToken(_tokenAddress)
returns (uint256 _requestId)
{
    // if depositing native token, then deposit to wrapped eth.
    if (msg.value > 0) {
        address _weth = WETH;
        _requestId = _deposit(_weth, _subaccount, msg.value);
        IWETH(_weth).deposit{ value: msg.value }(); // <<<
    } else {
        // transfer token to this contract
        _requestId = _deposit(_tokenAddress, _subaccount, _amount);
        IERC20(_tokenAddress).safeTransferFrom(msg.sender, address(this), _amount); // <<<
    }
}
```
But the sequencer can reject that transaction. The reason could be liquidatable account or some other reason. Because of this reject transaction, the requestId that was generated in the vault deposit is consumed:  
```solidity
function _executeAction(bytes memory _data) internal override {
    (uint256 _requestId, bytes32 _subaccount, uint256 _amount, address _tokenAddress, DepositAction _action) =
        abi.decode(_data, (uint256, bytes32, uint256, address, DepositAction));
    if (_subaccount != bytes32(0) && !isProcessed[_requestId]) {
        if (_action == DepositAction.Process) {
            IAssetService(assetService).adjustCollateral(_subaccount, _tokenAddress, _amount.toInt256());
            emit LogDepositProcessed(_subaccount, _tokenAddress, _amount);
        } else {
            emit LogDepositRejected(_subaccount, _tokenAddress, _amount); // <<<
        }
        isProcessed[_requestId] = true; // <<<
    }
}
```
And because of that, if now user try to withdraw his tokens using the Vault::withdraw(...) function, it will revert since the the withdraw function makes call to WithdrawHandler::getWithdrawableAmount(...) which will return zero as there was no collateral deposited in the user's position. Also there is no separate function to recover those tokens. They will remain stuck in the contract.

