        function _deployTokens(uint256 numTokens) internal {
            for (uint256 i; i < numTokens; i++) {
                _deployErc20Token();
                _deployErc721Token();
                _deployErc1155Token();
            }
        }

        function _deployErc20Token() internal returns (uint256 i) {
