```solidity
function _decrementWeightUntilFree(address user, uint256 weight) internal {
    uint256 userFreeWeight = balanceOf[user] - getUserWeight[user];

    // early return if already free
    if (userFreeWeight >= weight) return;

    uint32 currentCycle = _getGaugeCycleEnd();

    // cache totals for batch updates
    uint112 userFreed;
    uint112 totalFreed;

    // Loop through all user gauges, live and deprecated
    address[] memory gaugeList = _userGauges[user].values();

    // Free gauges until through entire list or under weight
    uint256 size = gaugeList.length;
    for (uint256 i = 0; i < size && (userFreeWeight + totalFreed) < weight; ) {
        address gauge = gaugeList[i];
        uint112 userGaugeWeight = getUserGaugeWeight[user][gauge];
        if (userGaugeWeight != 0) {
            // If the gauge is live (not deprecated), include its weight in the total to remove
            if (!_deprecatedGauges.contains(gauge)) {
                totalFreed += userGaugeWeight;
            }
            userFreed += userGaugeWeight;
            _decrementGaugeWeight(user, gauge, userGaugeWeight, currentCycle);

            unchecked {
                i++;
            }
        }
    }

    getUserWeight[user] -= userFreed;
    _writeGaugeWeight(_totalWeight, _subtract, totalFreed, currentCycle);
}
```

Consider Alice allocated 3 weight to gauge D, gauge A and gauge B equally where gauge D is depricated

1. Alice call _decrementWeightUntilFree(alice, 2)
2. userFreeWeight = 0
3. gauge D is freed, totalFreed = 0, userFreed = 1
4. (userFreeWeight + totalFreed) < weight, continue to free next gauge
5. gauge A is freed, totalFreed = 1, userFreed = 2
6. (userFreeWeight + totalFreed) < weight, continue to free next gauge
7. gauge B is freed, totalFreed = 2, userFreed = 3
8. All gauge is freed

Alternatively, Alice can

1. Alice call _decrementWeightUntilFree(alice, 1)
2. userFreeWeight = balanceOf[alice] - getUserWeight[alice] = 3 - 3 = 0
3. gauge D is freed, totalFreed = 0, userFreed = 1
4. (userFreeWeight + totalFreed) < weight, continue to free next gauge
5. gauge A is freed, totalFreed = 1, userFreed = 2
6. (userFreeWeight + totalFreed) >= weight, break
7. getUserWeight[alice] -= totalFreed
8. Alice call _decrementWeightUntilFree(alice, 2)
9. userFreeWeight = balanceOf[alice] - getUserWeight[alice] = 3 - 1 = 2
10. (userFreeWeight + totalFreed) >= weight, break
11. Only 2 gauge is freed

description:
Due to multiple underflow errors in _changeGaugeWeight, admin does not have the ability to reduce or set a gauge's weight to zero:
```solidity
// GaugeController.sol
function _changeGaugeWeight(address gauge, uint256 weight) internal {
    int128 gaugeType = gaugeTypes[gauge] - 1;
    uint256 oldGaugeWeight = _getWeight(gauge);
    uint256 typeWeight = _getTypeWeight(gaugeType);
    uint256 oldSum = _getSum(gaugeType);
    uint256 totalWeight = _getTotal();
    uint256 nextTimestamp = ((block.timestamp + WEEK) / WEEK) * WEEK;
    gaugeVotes[gauge][nextTimestamp] = weight;
    lastGaugeUpdate[gauge] = nextTimestamp;
    // @audit if weight is less than oldGaugeWeight, this will underflow
    uint256 newSum = oldSum + (weight - oldGaugeWeight);
    // @audit this will also underflow when new weight = 0
    totalWeight += (oldSum * weight) - (oldSum * typeWeight);
}
```
If weight is less than oldGaugeWeight, the calculation for newSum will underflow and revert. This is also true for calculation of totalWeight.
Impact: There are no ways for an admin to reduce the weight of a gauge or deprecate it by setting weight to zero.

In the Omnipool.deposit flow, the depositSingle function gets called of Aura Finance:
```solidity
function _depositToAuraPool(UnderlyingPool memory _pool, uint256 _underlyingAmountIn)
    internal
{
    uint256[] memory amountsIn = new uint256[](_pool.assets.length);
    // create join request
    uint256[] memory userDataAmountsIn = amountsIn;
    amountsIn[_pool.assetIndex] = _underlyingAmountIn;
    // if the assets include bpt, we must remove it from the amountsIn in the userData
    if (_pool.bptIndex > 0) {
        userDataAmountsIn = new uint256[](_pool.assets.length - 1);
        userDataAmountsIn[_pool.assetIndex - 1] = _underlyingAmountIn;
    }
    bytes memory userData =
        abi.encode(IBalancerVault.JoinKind.EXACT_TOKENS_IN_FOR_BPT_OUT, userDataAmountsIn, 2);
    // join balancer pool
    IRewardPoolDepositWrapper.JoinPoolRequest memory joinRequest = IRewardPoolDepositWrapper
        .JoinPoolRequest({
            assets: _pool.assets,
            maxAmountsIn: amountsIn,
            userData: userData,
            fromInternalBalance: false
        });
    // deposit into aura
    auraRewardPoolDepositWrapper.depositSingle(
        address(_pool.poolAddress),
        underlyingToken,
        _underlyingAmountIn,
        _pool.poolId,
        joinRequest
    );
}
```
If we take a look at this depositSingle function, we ﬁnd the following:
```solidity
function depositSingle(
    address _rewardPoolAddress,
    IERC20 _inputToken,
    uint256 _inputAmount,
    bytes32 _balancerPoolId,
    IBalancerVault.JoinPoolRequest memory _request
) external {
    // 1. Transfer input token
    _inputToken.safeTransferFrom(msg.sender, address(this), _inputAmount);
    // 2. Deposit to balancer pool
    (address pool, ) = bVault.getPool(_balancerPoolId);
    _inputToken.approve(address(bVault), _inputAmount);
    bVault.joinPool(_balancerPoolId, address(this), address(this), _request);
    uint256 minted = IERC20(pool).balanceOf(address(this));
    require(minted > 0, "!mint");
    uint256 inputBalAfter = _inputToken.balanceOf(address(this));
    if (inputBalAfter != 0) {
        // Refund any amount left in the contract
        _inputToken.transfer(msg.sender, inputBalAfter);
    }
    // 3. Deposit to reward pool
    IERC20(pool).approve(_rewardPoolAddress, minted);
    IRewardPool4626(_rewardPoolAddress).deposit(minted, msg.sender);
}
```
As you can see, in this line:
```solidity
_inputToken.transfer(msg.sender, inputBalAfter);
```
If there's any amount left, it will be refunded to the msg.sender. However, the msg.sender in this case will be the Omnipool.sol contract.
This means that the refund, which is meant for the person making a deposit, will not be credited to the person making the deposit but instead will be stuck in the Omnipool.sol contract, effectively losing a portion of the funds of the person who made the deposit.

