description:
After cross-chain multideposit arrives to the coreStateRegistry, the keeper will update the deposit first, before processing it through updateDepositPayload().
```solidity
function updateDepositPayload(uint256 payloadId_, uint256[] calldata finalAmounts_) external virtual override {
    _onlyAllowedCaller(keccak256("CORE_STATE_REGISTRY_UPDATER_ROLE"));
    // some code ...
    PayloadState finalState;
    if (isMulti != 0) {
        // See the line below
        (prevPayloadBody, finalState) = _updateMultiDeposit(payloadId_, prevPayloadBody, finalAmounts_);
    } else {
        // this will may or may not update the amount n prevPayloadBody .
        (prevPayloadBody, finalState) = _updateSingleDeposit(payloadId_, prevPayloadBody, finalAmounts_[0]);
    }
    // some code ...
}
```
In this case, the _updateMultiDeposit function is responsible for updating the deposit payload by resolving the final amounts given by the keeper. In this process, the failed deposits will be removed from the payload body and set to failedDeposit to be rescued later by the user.
```solidity
function _updateMultiDeposit(
    uint256 payloadId_,
    bytes memory prevPayloadBody_,
    uint256[] calldata finalAmounts_
)
    internal
    returns (bytes memory newPayloadBody_, PayloadState finalState_)
{
    /// some code ...
    uint256 validLen;
    for (uint256 i; i < arrLen; ++i) {
        if (finalAmounts_[i] == 0) {
            revert Error.ZERO_AMOUNT();
        }
        // update the amounts :
        (multiVaultData.amounts[i],, validLen) = _updateAmount(
            dstSwapper,
            multiVaultData.hasDstSwaps[i],
            payloadId_,
            i,
            finalAmounts_[i],
            multiVaultData.superformIds[i],
            multiVaultData.amounts[i],
            multiVaultData.maxSlippages[i],
            finalState_,
            validLen
        );
    }
    // update the payload body and remove the failed deposits
    if (validLen != 0) {
        uint256[] memory finalSuperformIds = new uint256[](validLen);
        uint256[] memory finalAmounts = new uint256[](validLen);
        uint256[] memory maxSlippage = new uint256[](validLen);
        bool[] memory hasDstSwaps = new bool[](validLen);
        uint256 currLen;
        for (uint256 i; i < arrLen; ++i) {
            if (multiVaultData.amounts[i] != 0) {
                finalSuperformIds[currLen] = multiVaultData.superformIds[i];
                finalAmounts[currLen] = multiVaultData.amounts[i];
                maxSlippage[currLen] = multiVaultData.maxSlippages[i];
                hasDstSwaps[currLen] = multiVaultData.hasDstSwaps[i];
                ++currLen;
            }
        }
        multiVaultData.amounts = finalAmounts;
        multiVaultData.superformIds = finalSuperformIds;
        multiVaultData.maxSlippages = maxSlippage;
        multiVaultData.hasDstSwaps = hasDstSwaps;
        finalState_ = PayloadState.UPDATED;
    } else {
        finalState_ = PayloadState.PROCESSED;
    }
    // return new payload
    newPayloadBody_ = abi.encode(multiVaultData);
}
```
The problem arises when some deposits fail and others succeed. The function doesn't update the retainERC4626 flags to match the new state: This misalignment can lead to incorrect minting behavior in the _multiDeposit function, where the retainERC4626 flags do not correspond to the correct superFormsIds.

The protocol lacks validation to ensure that the number of shares minted by a vault upon deposit aligns with the user's expectations, and the users have no choice but to accept any amount of shares resulted when depositing to a vault. This is particularly concerning for vaults that implement additional deposit strategies, which could be susceptible to front-running or other market manipulations. For example, a vault might use the deposited assets to engage in yield farming activities, where the number of shares minted to the depositor is dependent on the current state of the external protocol. If this protocol's conditions change rapidly (such as through front-running), the current protocol design exposes the users to front running attacks. See the following example from the _processDirectDeposit function of a superForm:
```solidity
function _processDirectDeposit(InitSingleVaultData memory singleVaultData_) internal returns (uint256 dstAmount) {
    // prev code ....
    if (singleVaultData_.retain4626) {
        //@audit : user can't refuse the amount of shares minted even if it's zero .
        // see the line below
        dstAmount = v.deposit(vars.assetDifference, singleVaultData_.receiverAddress);
    } else {
        // see the line below
        dstAmount = v.deposit(vars.assetDifference, address(this));
    }
}
function _directSingleDeposit( address srcSender_, bytes memory permit2data_,InitSingleVaultData memory vaultData_) internal virtual {
    // prev code ...
    // @audit : the contract mint any amount resulted from depositing , and the user have no control of that
    // see the line below
    if (dstAmount != 0 && !vaultData_.retain4626) {
        /// @dev mint super positions at the end of the deposit action if user doesn't retain 4626
        ISuperPositions(superRegistry.getAddress(keccak256("SUPER_POSITIONS"))).mintSingle(
            srcSender_, vaultData_.superformId, dstAmount
        );
    }
}
```
This could lead to users receiving fewer shares than anticipated if the vault's share price is affected by other on-chain activities. Recommendation: To mitigate this risk, the user should have the ability to specify his desired mintedAmount of shares when they are depositing to a superForm.

A malicious user can use multiple back and forth swaps to inﬂate the amount of deposit. The operator calling DstSwapper can process swaps in batch for a given payloadId. If the payload contains multiple swaps between tokenA and tokenB for amount X, the liquidity the sender needs to provide initially is only X tokenA. However, as all swaps are ﬁnished, there are N successful swaps each for X in token A and token B. This means that if otherwise the liquidity is available in DstSwapper, the sender can take it. This is due to the fact that DstSwapper only checks the target token increase during a swap, but does not register its decrease when used in another swap for the same payloadId.
```solidity
function _processTx(
    uint256 payloadId_,
    uint256 index_,
    uint8 bridgeId_,
    bytes calldata txData_,
    address userSuppliedInterimToken_,
    IBaseStateRegistry coreStateRegistry_
)
    internal
{
    // Unrelated validation logic
    ...
    /// @dev get the address of the bridge to send the txData to.
    (v.underlying, v.expectedAmount, v.maxSlippage) = _getFormUnderlyingFrom(coreStateRegistry_, payloadId_,
    index_);
    // See the line below
    v.balanceBefore = IERC20(v.underlying).balanceOf(v.finalDst);
    // Swap tokens in bridge
    // ...
    // See the line below
    v.balanceAfter = IERC20(v.underlying).balanceOf(v.finalDst);
    if (v.balanceAfter <= v.balanceBefore) {
        revert Error.INVALID_SWAP_OUTPUT();
    }
    // See the line below
    v.balanceDiff = v.balanceAfter - v.balanceBefore;
    /// @dev if actual underlying is less than expAmount adjusted
    /// with maxSlippage, invariant breaks
    /// @notice that unlike in CoreStateRegistry slippage check inside updateDeposit, in here we don't check for
    /// negative slippage
    /// @notice this essentially allows any amount to be swapped, (the invariant will still break if the amount is
    /// too low)
    /// @notice this doesn't mean that the keeper or the user can swap any amount, because of the 2nd slippage check
    /// in CoreStateRegistry
    /// @notice in this check, we check if there is negative slippage, for which case, the user is capped to receive
    /// the v.expAmount of tokens (originally defined)
    if (v.balanceDiff < ((v.expectedAmount * (10_000 - v.maxSlippage)) / 10_000)) {
        revert Error.SLIPPAGE_OUT_OF_BOUNDS();
    }
    /// @dev updates swapped amount
    // See the line below
    swappedAmount[payloadId_][index_] = v.balanceDiff;
    emit SwapProcessed(payloadId_, index_, bridgeId_, v.balanceDiff);
}
```
This strategy is conditioned on the fact that the malicious user Alice can get the operator to carry the swaps on the destination chain even though the liquidity of Alice has not been bridged correctly on destination chain. As such, this vulnerability is dependent on how off-chain infrastructures handle failed token bridging, but here are some strategies to get the bridging of tokens to fail intentionally:
• Supply unmatched deposit tokens/interim tokens for cross-chain deposit.
• Bridge tokens to a receiver address controlled by the attacker.
• Use gas parameter manipulation to make the call fail on destination chain. Therefore, a malicious user can steal liquidity contained in DstSwapper which, depending on off-chain infra, can be provided by other users.

Some endpoints of the LiFi bridge do not conform to the shape (ILiFi.BridgeData, /*...*/). In that case it is possible to craft a calldata which decodes to the tuple (ILiFi.BridgeData, /*...*/), but is also a valid input to the endpoint. In that case, validateTxData does not validate the right data, and the malicious user ends up bridging liquidity to themselves. This is possible because some endpoints on the LiFi diamond enable packing of calldata:
• HopFacetPacked:
– startBridgeTokensViaHopL2NativePacked
– startBridgeTokensViaHopL2NativeMin
• CBridgeFacetPacked:
– startBridgeTokensViaCBridgeNativePacked
– startBridgeTokensViaCBridgeNativeMin
– startBridgeTokensViaCBridgeERC20Packed
– startBridgeTokensViaCBridgeERC20Min
Let's take the example of CBridgeFacetPacked.startBridgeTokensViaCBridgeERC20Packed:
```solidity
function startBridgeTokensViaCBridgeERC20Min(
    bytes32 transactionId,
    address receiver,
    uint64 destinationChainId,
    address sendingAssetId,
    uint256 amount,
    uint64 nonce,
    uint32 maxSlippage
) external;
```
We see that it expects a calldata of the shape: (bytes32, address, uint64, address, uint256, uint64, uint32), which is static (no dynamic types). On the other hand, ILiFi.BridgeData is a dynamic struct, which means that the first 32 bytes word holds the offset at which the struct is located. In the case of the calldata for the packed endpoint, the first 32 bytes word is bytes32 transactionId, which is an arbitrary blob used for tracking/analytics. So we can easily craft a calldata which decodes validly for both cases:
```solidity
struct BridgeData {
    bytes32 transactionId;
    string bridge;
    string integrator;
    address referrer;
    address sendingAssetId;
    address receiver;
    uint256 minAmount;
    uint256 destinationChainId;
    bool hasSourceSwaps;
    bool hasDestinationCall;
}
function testEncodeCollision() public {
    //This variable acts as the transactionId during the actual call,
    //But also works as the offset for the encoding of the dynamic struct
    bytes32 transactionId = bytes32(uint(0x100));
    //Completely different receiver
    address receiver = address(1337);
    uint64 destinationChainId = 1;
    address sendingAssetId = address(3);
    uint256 amount = 1000;
    uint64 nonce = 1001;
    uint32 maxSlippage = 1002;
    bytes memory _calldata = abi.encode(
        transactionId,
        receiver,
        destinationChainId,
        sendingAssetId,
        amount,
        nonce,
        maxSlippage
    );
    BridgeData memory bridgeData = BridgeData(
        bytes32(uint(1)),
        'stargate',
        'jumper.exchange',
        address(1),
        address(2),
        //This is the receiver checked by `validateTxData`
        address(3),
        4,
        1,
        false,
        false
    );
    bytes memory bridgeDataEncoded = abi.encode(bridgeData);
    // We concat both encodings
    _calldata = abi.encodePacked(_calldata, bridgeDataEncoded);
    // First we can decode the format needed for the endpoint
    (, address actualReceiver, , , , ,) = abi.decode(_calldata, (
        bytes32,
        address,
        uint64,
        address,
        uint256,
        uint64,
        uint32
    ));
    // But we can also decode the format needed for validateTx
    BridgeData memory bridgeDataDecoded = abi.decode(_calldata, (
        BridgeData
    ));
    assert(bridgeDataDecoded.receiver == bridgeData.receiver);
    assert(actualReceiver == address(1337));
    console.logBytes(_calldata);
}
```
A malicious user can use this to bypass validateTx checks, and send tokens to themselves on the destination chain. Depending on the mechanism implemented off-chain, it can be tricked into using liquidity already available in DstSwapper, since the bridging will succeed.

The intended functionality of _dispatchTokens is to enable users to bridge tokens or conduct token swaps through the 1inch exchange, utilizing low-level calls (see LiquidityHandler.sol#L33):
```solidity
function _dispatchTokens(
    address bridge_,
    bytes memory txData_,
    address token_,
    uint256 amount_,
    uint256 nativeAmount_
)
    internal
    virtual
{
    if (bridge_ == address(0)) {
        revert Error.ZERO_ADDRESS();
    }
    if (token_ != NATIVE) {
        IERC20 token = IERC20(token_);
        token.safeIncreaseAllowance(bridge_, amount_);
    } else {
        if (nativeAmount_ < amount_) revert Error.INSUFFICIENT_NATIVE_AMOUNT();
    }
    (bool success,) = payable(bridge_).call{ value: nativeAmount_ }(txData_);
    if (!success) revert Error.FAILED_TO_EXECUTE_TXDATA(token_);
}
```
Address bridge is expected to be either Liﬁaddress or 1inch address. This function is usually called in this way:
```solidity
/// @dev dispatches tokens through the selected liquidity bridge to the destination contract
_dispatchTokens(
    superRegistry.getBridgeAddress(args_.liqRequest.bridgeId),
    args_.liqRequest.txData,
    args_.liqRequest.token,
    IBridgeValidator(bridgeValidator).decodeAmountIn(args_.liqRequest.txData, true),
    args_.liqRequest.nativeAmount
);
```
However, malicious admin can whitelist a malicious address so the query superRegistry.getBridgeAddress(args_.liqRequest.bridgeId) can return a token address. Consider the case:
1. A user grants infinite spending allowance to the router for UDSC token.
2. Admin is compromised and a hacker whitelists the USDC token address for bridge id 1000. So, superRegistry.getBridgeAddress(args_.liqRequest.bridgeId) returns the USDC address
3. The hacker craft the following payload data: abi.encodeWithSelector(IERC20.transferFrom.selector, address(victim), address(hacker), userUSDCBalance)
4. Then the hacker can steal the USDC that sits in users wallet by using the following low-level call: (bool success,) = payable(bridge_).call{ value: nativeAmount_ }(txData_);

When depositing to the vault, users can make deposits on behalf of other users by specifying the receiver address. If the user doesn't retain 4626, the function will mint super positions at the end of the deposit action.
```solidity
if (dstAmount != 0 && !vaultData_.retain4626) {
    /// @dev mint super positions at the end of the deposit action if user doesn't retain 4626
    ISuperPositions(superRegistry.getAddress(keccak256("SUPER_POSITIONS"))).mintSingle(
        srcSender_, vaultData_.superformId, dstAmount
    );
}
```
The issue occurs when the user wants to deposit to another address but doesn't want to keep 4626, resulting in the super position being minted for the msg.sender instead of the receiver address.

The protocol allows any vault owner from adding their vaults to the protocol by wrapping them to one of the approved form implementations. These vaults can have any type of underlying assets including fee-on-transfer token type; which deducts a fee from the transferred amount, so the resulting final balance of the receiver would be less than the sent amount by the amount of the deducted fees. It was noticed that the protocol doesn't support such type of tokens; users can't deposit in vaults with fee-on-transfer tokens due to this check made in the ERC4626FormImplementation._processDirectDeposit function
```solidity
vars.assetDifference = IERC20(vars.asset).balanceOf(address(this)) - vars.balanceBefore;
/// @dev the difference in vault tokens, ready to be deposited, is compared with the amount inscribed in the
/// superform data
if (vars.assetDifference < singleVaultData_.amount) {
    revert Error.DIRECT_DEPOSIT_INVALID_DATA();
}
```
where vars.assetDifference will always be less than singleVaultData_.amount due to the deducted fees (for fee-on-transfer underlying vault token).

The admin can call setRequiredMessagingQuorum to set requiredQuorum:
```solidity
function setRequiredMessagingQuorum(uint64 srcChainId_, uint256 quorum_) external override onlyProtocolAdmin {
    requiredQuorum[srcChainId_] = quorum_;
    emit QuorumSet(srcChainId_, quorum_);
}
```
And the message can only be processed if the number of proof messages received is greater than the requiredQuorum:
```solidity
if (messageQuorum[payloadProof] < _getQuorum(srcChainId)) {
    revert Error.INSUFFICIENT_QUORUM();
}
```
The problem here is that when a cross-chain message is initiated, the length of its ambIds is ﬁxed, i.e. the number of messages sent is ﬁxed, which also means that the number of received proof messages, i.e. messageQuorum, will not exceed it. If setRequiredMessagingQuorum is called to increase the requiredQuorum between the initiation and processing of a cross-chain message, then when the cross-chain message is processed, it will not be processed due to insufficient messageQuorum:
1. Consider chain A with requiredQuorum 3, a user initiates a cross-chain deposit with ambIds length 4.
2. When the message is successfully dispatched, admin calls setRequiredMessagingQuorum to increase the requiredQuorum to 5.
3. When the destination chain processes the message, the message will not be processed because the messageQuorum is at most 4 and less than 5.

The keeper will always overwrite the txData when updating the withdrawal payload in case
of a single withdrawal, while it shouldn't be updated if the user already provided a txData like in multi-
withdrawal behavior.
The updateWithdrawPayload function within the CoreStateRegistry contract plays the role of updating the
withdrawal payload with a (txData_) provided by the keeper. Particularly, in the _updateWithdrawPayload
function:
```solidity
// updateWithdrawPayload function
// ...
// see the line below
prevPayloadBody = _updateWithdrawPayload(prevPayloadBody, srcSender, srcChainId, txData_, isMulti);
// more code ..
```
This function is expected to call _updateTxData to conditionally update the payload with the keeper's
txData_:
```solidity
// _updateWithdrawPayload() function
// ...
// see the line below
multiVaultData = _updateTxData(txData_, multiVaultData, srcSender_, srcChainId_, CHAIN_ID);
// more code ..
```
The _updateTxData function should leave the user's txData unchanged if it is already provided (i.e. if its
length is not zero):
```solidity
function _updateTxData(/*....*/ ) internal view returns (InitMultiVaultData memory){
    uint256 len = multiVaultData_.liqData.length;
    for (uint256 i; i < len; ++i) {
        // see the line below
        if (txData_[i].length != 0 && multiVaultData_.liqData[i].txData.length == 0) {
            // ...
        }
    }
    return multiVaultData_;
}
```
In case of singleWithdraw, regardless of whether the user's txData was provided or not, the function will
always overwrite the user's singleVaultData.liqData.txData to txData_[0], which is the keeper's data,
instead of the txData returned from _updateTxData, which will not be the keeper txData in case user
provided data:
```solidity
function _updateWithdrawPayload( bytes memory prevPayloadBody_, address srcSender_, uint64 srcChainId_,
    bytes[] calldata txData_,uint8 multi )internal
    view returns (bytes memory){
    // prev code ..
    multiVaultData = _updateTxData(txData_, multiVaultData, srcSender_, srcChainId_, CHAIN_ID);
    if (multi == 0) {
        // @audit-issue : the keeper will always overwrite the txData,should be
        // see the line below
        singleVaultData.liqData.txData = txData_[0];
        return abi.encode(singleVaultData);
    }
    return abi.encode(multiVaultData);
}
```
The correct behavior should ensure that the user's txData is preserved when provided (like in multi-
withdrawal), and the keeper's txData is only employed if the user's ‘txData“ is absent.
The impact however is somewhat unclear in this scenario because of the unknown keeper behavior. Nev-
ertheless, due to the validation process prior to executing the txData, there are some potential issues in
case of a maliciously txData passing the validation:
1. The amountIn for the swap can be set to an undesirably low value, causing the withdrawn amounts
of the user to swap only a small portion, with the remainder staying in the superForm.
2. The ﬁnal received token after the swap to any token can be altered (e.g. swapping from USDC to
WETH, the keeper might set it to swap from USDC to any Token).
3. The behavior of the txData can be changed (e.g. from swap and bridge, to only swap).

When users want to deposit to superforms directly in the same chain, they can call sin-
gleDirectSingleVaultDeposit or singleDirectMultiVaultDeposit (see SuperformRouter.sol#L25-L34)
```solidity
/// @inheritdoc IBaseRouter
function singleDirectSingleVaultDeposit(SingleDirectSingleVaultStateReq memory req_)
    external
    payable
    override(BaseRouter, IBaseRouter)
{
    uint256 balanceBefore = address(this).balance - msg.value;
    _singleDirectSingleVaultDeposit(req_);
    _forwardPayment(balanceBefore);
}
```
Also see SuperformRouter.sol#L49-L58:
```solidity
function singleDirectMultiVaultDeposit(SingleDirectMultiVaultStateReq memory req_)
    external
    payable
    override(BaseRouter, IBaseRouter)
{
    uint256 balanceBefore = address(this).balance - msg.value;
    _singleDirectMultiVaultDeposit(req_);
    _forwardPayment(balanceBefore);
}
```
In these functions, user can provide max slippage as parameters and will be passed to superform when
trigger directDepositIntoVault.
```solidity
struct SingleDirectSingleVaultStateReq {
    SingleVaultSFData superformData;
}

struct SingleVaultSFData {
    // superformids must have same destination. Can have different underlyings
    uint256 superformId;
    uint256 amount;
    uint256 maxSlippage;
    LiqRequest liqRequest; // if length = 1; amount = sum(amounts)| else
    amounts must match the amounts being
    sent
    bytes permit2data;
    bool hasDstSwap;
    bool retain4626; // if true, we don't mint SuperPositions, and send the 4626 back to the user instead
    address receiverAddress;
    bytes extraFormData; // extraFormData
}

struct SingleDirectMultiVaultStateReq {
    MultiVaultSFData superformData;
}

struct MultiVaultSFData {
    // superformids must have same destination. Can have different underlyings
    uint256[] superformIds;
    uint256[] amounts;
    uint256[] maxSlippages;
    LiqRequest[] liqRequests; // if length = 1; amount = sum(amounts) | else
    amounts must match the amounts
    being sent
    bytes permit2data;
    bool[] hasDstSwaps;
    bool[] retain4626s; // if true, we don't mint SuperPositions, and send the 4626 back to the user instead
    address receiverAddress;
    bytes extraFormData; // extraFormData
}
```
Also see BaseRouterImplementation.sol#L556-L589:
```solidity
function _directDeposit(
    address superform_,
