    uint256 msgValue_,
    address srcSender_
)
    internal
    virtual
    returns (uint256 dstAmount)
{
    /// @dev deposits token to a given vault and mint vault positions directly through the form
    dstAmount = IBaseForm(superform_).directDepositIntoVault{ value: msgValue_ }(
        InitSingleVaultData(
            payloadId_,
            superformId_,
