    skipDepositDuration();
    skipPurchaseDelay();
    // Pause the set.
    for (uint256 i = 0; i < 45000; i++) {
        vm.prank(pauser);
        set.pause();
        skip(12);
        SetState setState = set.setState();
        vm.prank(owner);
        set.unpause();
    }
    uint256 checkpointGasLeft = gasleft();
    triggerMarket(0);
    console2.log("Gas used: %s", checkpointGasLeft - gasleft());
    checkpointGasLeft = gasleft();
    claimMax(buyerA, 0);
    console2.log("Gas used: %s", checkpointGasLeft - gasleft());
}
