                transferData: abi.encode(amount, _l2Receiver),
                _passValue: false
            });
```

In AssetRouterBase.sol, the _burn function calls IAssetHandler(l1AssetHandler).bridgeBurn:

```solidity
AssetRouterBase.sol
function _burn(
        uint256 _chainId,
        uint256 _nextMsgValue,
        bytes32 _assetId,
        address _originalCaller,
        bytes memory _transferData,
        bool _passValue
    ) internal returns (bytes memory bridgeMintCalldata) {
        address l1AssetHandler = assetHandlerAddress[_assetId];
        if (l1AssetHandler == address(0)) {
            revert AssetHandlerDoesNotExist(_assetId);
        }

        uint256 msgValue = _passValue ? msg.value : 0;
        bridgeMintCalldata = IAssetHandler(l1AssetHandler).bridgeBurn{value: msgValue}({
            chainId: chainId,
            msgValue: nextMsgValue,
            assetId: assetId,
            originalCaller: originalCaller,
            data: transferData
        });
    }
```

The BridgedToken is initialized with the assetHandlerAddress[assetId] as nativeTokenVault:

```solidity
 function _finalizeDeposit(
        uint256 _chainId,
        bytes32 _assetId,
        bytes calldata _transferData,
        address _nativeTokenVault
    ) internal {
        address assetHandler = assetHandlerAddress[_assetId];

        if (assetHandler != address(0)) {
            IAssetHandler(assetHandler).bridgeMint(chainId, assetId, _transferData);
        } else {
            assetHandlerAddress[assetId] = nativeTokenVault;
            IAssetHandler(nativeTokenVault).bridgeMint(chainId, assetId, transferData);
        }
    }
```

Since the BridgedToken's assetHandlerAddress is nativeTokenVault, the burn function will trigger NativeTokenVault::bridgeBurn which calls the _bridgeBurnBridgedToken function:

```solidity
NativeTokenVault.sol
 function bridgeBurn(
        uint256 _chainId,
        uint256,
        bytes32 _assetId,
        address _originalCaller,
        bytes calldata _data
    ) external payable override onlyAssetRouter whenNotPaused returns (bytes memory _bridgeMintData) {
        if (originChainId[_assetId] != block.chainid) {
            bridgeMintData = bridgeBurnBridgedToken(chainId, assetId, originalCaller, data);
        } else {
        //////////////////////////////////////
    }

    function _bridgeBurnBridgedToken(
        uint256 _chainId,
        bytes32 _assetId,
        address _originalCaller,
        bytes calldata _data
    ) internal returns (bytes memory _bridgeMintData) {
        (uint256 amount, address receiver) = abi.decode(_data, (uint256, address));
        if (_amount == 0) {
            // "Amount cannot be zero");
            revert AmountMustBeGreaterThanZero();
        }

        address bridgedToken = tokenAddress[_assetId];
        IBridgedStandardToken(bridgedToken).bridgeBurn(originalCaller, amount);
        handleChainBalanceIncrease(chainId, assetId, amount, false);
```

As a result, whenever the user bridges the BridgedToken, the contract deducts double the amount of the user's BridgedToken. L1ERC20Bridge takes the user's BridgedToken by calling transferFrom to transfer the user's BridgedToken into the L1ERC20Bridge contract. NativeTokenVault burns the BridgedToken from the user. If the user still has remaining BridgedToken, they will lose their funds because bridging the BridgedToken causes the contract to take double the amount. If the user has no remaining BridgedToken, the transaction will fail.

