    function initFromCommitment(Tree storage tree, PriorityTreeCommitment memory commitment) internal {
        uint256 height = _commitment.sides.length; // Height, including the root node.
        if (height == 0) {
            revert InvalidCommitment();
        }
        tree.startIndex = commitment.startIndex;
        tree.unprocessedIndex = commitment.unprocessedIndex;
        tree.tree.nextLeafIndex = _commitment.nextLeafIndex;
        tree.tree.sides = _commitment.sides;
        bytes32 zero = ZEROLEAFHASH;
        tree.tree.zeros = new bytes32[](height);
        for (uint256 i; i < height; ++i) {
