description:
The `Gauge.notifyRewardAmount` notifies the contract of a newly received rewards. This updates the local accounting and streams the reward over a preset period (Five days).

It was observed that this function is callable by anyone regardless of whether the previous reward period has already expired or not. Thus, it would be possible to exploit the system by repeatedly calling it with dust reward amount to extend an active reward period, and thus dragging out the duration over which the rewards are released.

Since Velodrome is to be deployed on Layer 2 blockchain where the gas fee tends to be cheap, the effort required to carry out this attack would be minimal.

This issue was also highlighted in Curve documentation under the [`ChildChainStreamer.notify_reward_amount(token: address):`](https://curve.readthedocs.io/dao-gauges-sidechain.html) section.

[Gauge.sol#L590](https://github.com/code-423n4/2022-05-velodrome/blob/7fda97c570b758bbfa7dd6724a336c43d4041740/contracts/contracts/Gauge.sol#L590)
```solidity
function notifyRewardAmount(address token, uint amount) external lock {
    require(token != stake);
    require(amount > 0);
    if (!isReward[token]) {
        require(rewards.length < MAX_REWARD_TOKENS, "too many rewards tokens");
    }
    // rewards accrue only during the bribe period
    uint bribeStart = block.timestamp - (block.timestamp % (7 days)) + BRIBE_LAG;
    uint adjustedTstamp = block.timestamp < bribeStart ? bribeStart : bribeStart + 7 days;
    if (rewardRate[token] == 0) _writeRewardPerTokenCheckpoint(token, 0, adjustedTstamp);
    (rewardPerTokenStored[token], lastUpdateTime[token]) = _updateRewardPerToken(token);
    _claimFees();

    if (block.timestamp >= periodFinish[token]) {
        _safeTransferFrom(token, msg.sender, address(this), amount);
        rewardRate[token] = amount / DURATION;
    } else {
        uint _remaining = periodFinish[token] - block.timestamp;
        uint _left = _remaining * rewardRate[token];
        require(amount > _left);
        _safeTransferFrom(token, msg.sender, address(this), amount);
        rewardRate[token] = (amount + _left) / DURATION;
    }
    require(rewardRate[token] > 0);
    uint balance = IERC20(token).balanceOf(address(this));
    require(rewardRate[token] <= balance / DURATION, "Provided reward too high");
    periodFinish[token] = adjustedTstamp + DURATION;
    if (!isReward[token]) {
        isReward[token] = true;
        rewards.push(token);
        IBribe(bribe).addRewardToken(token);
    }

    emit NotifyReward(msg.sender, token, amount);
}
```

The HolofairToken contract includes a pausePresale function that allows the creator to pause the presale. However, the only way to resume the presale after it has been paused is by calling the startPresale function. This approach inadvertently resets the fundraisingEndTime by adding the fundraisingPeriod to the current block timestamp, effectively extending the presale duration. This extension can disrupt the vesting schedule for users who have already deposited funds, as their vesting unlock time is tied to the original fundraisingEndTime.
```solidity
function startPresale() external {
    require(msg.sender == creator, "Only creator can start presale");
    require(!presaleActive, "Presale already started");
    fundraisingEndTime = block.timestamp + fundraisingPeriod;
    presaleActive = true;
}
function pausePresale() external {
    require(msg.sender == creator, "Only creator can pause presale");
    require(presaleActive, "Presale already paused");
    presaleActive = false;
}
```

The withdrawDeposit function in the HolofairToken contract is designed to allow users to withdraw their deposited funds during the presale. However, the current implementation restricts withdrawals to only when the presale is active. This means that if the presale is paused, users are unable to withdraw their funds. Since the presale can be paused indefinitely, this creates a risk where users' deposited funds could be locked forever.
```solidity
function withdrawDeposit(uint256 amount) external nonReentrant {
    require(presaleActive, "Presale not active");
    uint256 userDeposit = deposits[msg.sender];
    require(userDeposit >= amount, "Insufficient deposit");
    // Reset the user's deposit before transferring to prevent reentrancy
    deposits[msg.sender] -= amount;
    totalRaised -= amount;
    (bool success, ) = msg.sender.call{value: amount}("");
    require(success, "Withdrawal failed");
    emit WithdrawDeposit(msg.sender, 0, amount);
}
```

If the randomizer selects a jar that is already fermented, a collission occurs.
```solidity
function _setFermentedJars(uint256[] memory randomNumbers) internal {
    ---SNIP---
    for (uint256 i = 0; i < numFermentedJars; i++) {
        fermentedIndex = randomNumbers[i] % numHoneyJars;
        uint256 fermentedJarId = honeyJarIds[fermentedIndex];
        if (honeyJar.isFermented(fermentedJarId)) {
            // Special case in the event of a collision -- not optimized for gas
            fermentedJarId = _findNextJar(fermentedJarId);
