    address _swapper,
    address _debtAsset,
    address _yieldAsset,
    uint256 _initialAmount,
    uint256 _flashloanAmount,
    uint256 _minAmountOut,
    address[] memory _path,
    bool _startWithYield
) external nonReentrant {
    require(pools[_pool], "pool not allowed");
    if (_startWithYield) {
        //transfer initial _yieldAsset from user
        IERC20(_yieldAsset).transferFrom(
            msg.sender,
            address(this),
            _initialAmount
        );
        uint256 minAmountOut = (((_flashloanAmount * 1e8) / _minAmountOut) *
        _initialAmount) / 1e8;
        _initialAmount = _swap(
            _swapper,
            _reversePath(_path),
            _initialAmount,
            minAmountOut
        );
    } else {
        //...
    }
    //...
```
If the _initialAmount is in yieldAsset, then a swap is done to get the _initialAmount in debtAsset, where the minAmountOut expected from the swap is calculated as follows:
```solidity
uint256 minAmountOut = ((
(_flashloanAmount * 1e8) / _minAmountOut) * _initialAmount) / 1e8;
```
Where in this case:
_flashloanAmount: the amount of the _debtAsset to be flashloaned then swapped to _yieldAsset
_minAmountOut: minimum amount of _yieldAsset expected to be received after swapping _debtAsset
_initialAmount: the initial amount of the _yieldAsset provided by the user
But as can be noticed, the minAmountOut calculation assumes that both _debtAsset and _yieldAsset have the same valuation, which is incorrect, for example:
a user flashloans 100_000 USDC, while the _minimumAmountOut of WBTC to be received is 0.9995 WBTC with 0.05% acceptable slippage (assuming the price of 1WBTC is 100_000USDC),
assuming that the flashloan premium is set to 0.1% of the flashloan amount, the user will provide 100USDC equivalent of WBTC to execute the openPosition(), which is 0.001 WBTC
so the calculated minAmountOut would be 100.050025 in USDC decimals which is > the value of the provided _initialAmount:
minAmountOut = ((
(100_000*1e6 * 1e8) / 0.9995*1e8) * 0.001*1e8) / 1e8 = 100.050025 in USDC decim
This will result in calculating minAmountOut > _initialAmount when swapping, which will result in reverting the transaction.

In the current implementation of the addLiquidity() function, a malicious user can exploit the Fenwick Tree structure by adding liquidity multiple times on behalf of another user, effectively filling the tree and potentially preventing legitimate deposits from occurring. The Fenwick Tree has a maxDepositEntries limit, and once this limit is reached, no more entries can be added. This enables griefing behavior, where an attacker could manipulate the system by adding multiple deposits for a single user, thus locking out legitimate users from depositing liquidity until the tree is reset.
```solidity
function _deposit(
FenwicksDatastorage self,
uint256 maxDepositEntries,
uint256 lockDuration,
uint256 amount
) internal
    uint256 treeIndex = _registerKey
    (self, maxDepositEntries, block.timestamp + lockDuration);
    _fenwicksUpdate(self, maxDepositEntries, treeIndex, amount);
    self.totalMintedPLP += amount;
function _registerKey(
FenwicksDatastorage self,
uint256 maxDepositEntries,
uint256 newTimestamp
) internal
returns (uint256 treeIndex)
    uint256 keyCount = self.sortedKeys.length;
    if (keyCount >= maxDepositEntries) revert Fenwicks_TooManyKeys();
    self.sortedKeys.push(newTimestamp);
    self.keyToIndex[newTimestamp] = ++keyCount;
    treeIndex = self.keyToIndex[newTimestamp];
```
Although users can withdraw all liquidity to reset the tree, this action can only be performed after the lock duration has passed, which may lead to prolonged periods where malicious behavior can persist.

