            );

            uint256 ve3TokenBalance = IERC20(rewardTokenInfo[_rewardToken].ve3Token).balanceOf(
                address(this)
            );
            if (_stake) {
                IERC20(rewardTokenInfo[_rewardToken].ve3Token).safeApprove(
                    rewardTokenInfo[_rewardToken].ve3TokenRewards,
                    0
                );
                IERC20(rewardTokenInfo[_rewardToken].ve3Token).safeApprove(
                    rewardTokenInfo[_rewardToken].ve3TokenRewards,
                    ve3TokenBalance
                );
                IRewards(rewardTokenInfo[_rewardToken].ve3TokenRewards).stakeFor(
                    _account,
                    ve3TokenBalance
                );
            } else {
                IERC20(rewardTokenInfo[_rewardToken].ve3Token).safeTransfer(
                    _account,
                    ve3TokenBalance
                );
            }
            emit RewardPaid(_account, ve3TokenBalance);
        }
    }

    //also get rewards from linked rewards
    if (_claimExtras) {
        uint256 length = extraRewards.length;
        for (uint256 i = 0; i < length; i++) {
            IRewards(extraRewards[i]).getReward(_account);
        }
    }
}
```

As you can see it loops through all `rewardTokens` and in line `314` it transfers all balance of `rewardTokenInfo[_rewardToken].ve3Token` of contract to `account` address. So if `owner` by mistake or bad intention add a new `rewardToken` that `rewardTokenInfo[newRewardToken].ve3Token == oldRewardToken` then by calling `getReward(account, False, False)` contract will loop through all reward tokens and when it reaches the `newRewardToken` it will transfer all the balance of contract in `rewardTokenInfo[newRewardToken].ve3Token` address to account address and `rewardTokenInfo[newRewardToken].ve3Token` is `oldRewardToken`, so it will transfer all the `oldRewardToken` balance of contract (which was supposed to be distributed among all stakers) to account address. This is like a backdoor that gives `owner` the ability to withdraw rewards tokens and if owner makes a simple mistake then one can easily withdraw that contract balance of reward token.

