```javascript
StakingRewardsPool.sol

    function mint(address recipient, uint256 _amount) internal override {
        uint256 sharesToMint = getSharesByStake(_amount);
        mintShares(recipient, sharesToMint);

        emit Transfer(address(0), recipient, amount);
    }

    function mintShares(address recipient, uint256 _amount) internal {
        require(_recipient != address(0), "Mint to the zero address");

        if (totalShares == 0) {
            shares[address(0)] = DEAD_SHARES;
