The MorphoGovernance contract allow Morpho to set the isBorrowPaused to false only if the market is not deprecated.
```solidity
function setIsBorrowPaused(address _poolToken, bool _isPaused)
external
onlyOwner
isMarketCreated(_poolToken)
{
    if (!_isPaused && marketPauseStatus[_poolToken].isDeprecated) revert MarketIsDeprecated();
    marketPauseStatus[_poolToken].isBorrowPaused = _isPaused;
    emit IsBorrowPausedSet(_poolToken, _isPaused);
}
```
This check is not enforced by the _setPauseStatus function, called by setIsPausedForAllMarkets allowing Morpho to resume borrowing for deprecated market.
Test to reproduce the issue
```solidity
// SPDX-License-Identifier: AGPL-3.0-only
pragma solidity ^0.8.0;
import "./setup/TestSetup.sol";
contract TestSpearbit is TestSetup {
    using WadRayMath for uint256;
    function testBorrowPauseCheckSkipped() public {
        // Deprecate a market
        morpho.setIsBorrowPaused(aDai, true);
        morpho.setIsDeprecated(aDai, true);
        checkPauseEquality(aDai, true, true);
        // you cannot resume the borrowing if the market is deprecated
        hevm.expectRevert(abi.encodeWithSignature("MarketIsDeprecated()"));
        morpho.setIsBorrowPaused(aDai, false);
        checkPauseEquality(aDai, true, true);
        // but this check is skipped if I call directly `setIsPausedForAllMarkets`
        morpho.setIsPausedForAllMarkets(false);
        // this should revert because
        // you cannot resume borrowing for a deprecated market
        checkPauseEquality(aDai, false, true);
    }
    function checkPauseEquality(
        address aToken,
        bool shouldBePaused,
        bool shouldBeDeprecated
    ) public {
        (
            bool isSupplyPaused,
            bool isBorrowPaused,
            bool isWithdrawPaused,
            bool isRepayPaused,
            bool isLiquidateCollateralPaused,
            bool isLiquidateBorrowPaused,
            bool isDeprecated
        ) = morpho.marketPauseStatus(aToken);
        assertEq(isBorrowPaused, shouldBePaused);
        assertEq(isDeprecated, shouldBeDeprecated);
    }
}
```

Currently, when a market must be deprecated, Morpho checks that borrowing has been paused before applying the new value for the flag.
```solidity
function setIsDeprecated(address _poolToken, bool _isDeprecated)
external
onlyOwner
isMarketCreated(_poolToken)
{
    if (!marketPauseStatus[_poolToken].isBorrowPaused) revert BorrowNotPaused();
    marketPauseStatus[_poolToken].isDeprecated = _isDeprecated;
    emit IsDeprecatedSet(_poolToken, _isDeprecated);
}
```
The same check should be done in isLiquidateBorrowPaused, allowing the deprecation of a market only if isLiquidateBorrowPaused == false otherwise liquidators would not be able to liquidate borrowers on a deprecated market.

In the _swap() function in the MobiusRouter contract, there is an issue when the poolPath contains duplicate pool addresses. Each pool’s swap() function is protected by the conditionallySingleCallPerTransaction() modifier, which is designed to prevent more than one call to the function per transaction:
```solidity
function _swap(address[] calldata tokenPath , address[] calldata poolPath ,
uint256 fromAmount , address to)
internal
returns (uint256 amountOut , uint256 haircut)
{
// [code omitted for brevity]
for (uint256 i; i < poolPath.length; ++i) {
// [code omitted for brevity]
// make the swap with the correct arguments
(amountOut , localHaircut) = IPool(poolPath[i]).swap(
tokenPath[i],
tokenPath[i + 1],
nextFromAmount ,
0, // minimum amount received is ensured on calling function
nextTo ,
type(uint256).max // deadline is ensured on calling function
);
// [code omitted for brevity]
}
}
```
The conditionallySingleCallPerTransaction() modifier works by checking the gas consumed when accessing an address’s balance:
```solidity
modifier conditionallySingleCallPerTransaction() {
if (coldAccessGasCost != -1) {
address addressToCheck = address(uint160(bytes20(blockhash(block.number))));
uint256 initialGas = gasleft();
uint256 temp = addressToCheck.balance;
uint256 gasConsumed = initialGas - gasleft();
if (gasConsumed != uint256(coldAccessGasCost)) revert AlreadyCalledInThisTransaction();
}
_;
}
```
When a pool’s swap() function is called multiple times in the same transaction, the second call will revert with the AlreadyCalledInThisTransaction error. This means that any router transaction with a poolPath containing duplicate pool addresses will fail. But the protocol design allows pools to support multiple assets (as shown in StablePool and VariantPool ), so this creates a limitation in constructing efficient swap paths.
```solidity
function addAsset(address token, address asset) external onlyOwner {
if (token == address(0)) revert Pool_AddressShouldNotBeZero();
if (asset == address(0)) revert Pool_AddressShouldNotBeZero();
if (_containsAsset(token)) revert Pool_AssetAlreadyExists();
_addAsset(token, VariantAsset(asset));
emit AssetAdded(token, asset);
}
```
For example:
1. PoolA has USDC, USDT, and ETH, while PoolB only has USDT and ETH.
2. A user spots a price gap in ETH between the pools, creating an arbitrage opportunity. Their swap strategy is:
   - PoolA: USDC → ETH
   - PoolB: ETH → USDT
   - PoolA: USDT → USDC
3. This is a valid arbitrage strategy, but MobiusRouter.swapTokensForTokens() can’t execute it. Any router transaction with a poolPath containing duplicate pool addresses will fail. But the protocol design allows pools to support multiple assets (as shown in StablePool and VariantPool), so this creates a limitation in constructing efficient swap paths.

When a user deposits in the swappool, the latest deposit block number is registered. This is to prevent users from immediately redeeming swappool lp tokens for backstop assets through the backstopBurn function without first waiting for the needed insurance period. However, the way this is tracked, involves a direct mapping of the block.number to the sender, as such, every new deposit a user makes overwrites the previously tracked block.number. As result, serious pool depositors will be forced to wait longer for time periods before being able to redeem their lptokens.  
