    if (block.timestamp > forkingPeriodEndTimestamp) revert OnlyDuringForkingPeriod();
    for (uint256 i = 0; i < tokenIds.length; i++) {
        uint256 nounId = tokenIds[i];
        _mintWithOriginalSeed(to, nounId);
