 * @param _token The address of the token
 * @param _liquidityFee The liquidity fee amount
 * @param _receiver The address of the receiver
 * @return Sponsored liquidity fee amount
 */
function reimburseLiquidityFees(
  address _token,
  uint256 _liquidityFee,
  address _receiver
) external override onlyConnext returns (uint256) {
  uint256 sponsoredFee;

  if (address(tokenExchanges[_token]) != address(0)) {
    uint256 currentBalance = address(this).balance;
    ITokenExchange tokenExchange = tokenExchanges[_token];

    uint256 amountIn = tokenExchange.getInGivenExpectedOut(_token, _liquidityFee);
    amountIn = currentBalance >= amountIn ? amountIn : currentBalance;

    // sponsored fee may end being less than _liquidityFee due to slippage
    sponsoredFee = tokenExchange.swapExactIn{value: amountIn}(_token, msg.sender);
  } else {
    uint256 balance = IERC20(_token).balanceOf(address(this));
    sponsoredFee = balance < _liquidityFee ? balance : _liquidityFee;

    // some ERC20 do not allow to transfer 0 amount
    if (sponsoredFee > 0) {
      IERC20(_token).safeTransfer(msg.sender, sponsoredFee);
    }
  }

  emit ReimburseLiquidityFees(_token, sponsoredFee, _receiver);

  return sponsoredFee;
}
```

As you can see there is no slippage defined when calling `swapExactIn()` can that swap could happen in any exchange rate. it’s possible to perform sandwich attack and do large swap before and after the transaction and make users lose funds. and it’s also MEV opportunity.

description:
The protocol lacks functionality to remove fee recipients from protocolFeeRecipients. The only way to "disable" a recipient is by setting their share to zero, but they remain in the Enumerable Mapping and still receive transfer calls. This can cause entire reward distributions to fail if any recipient becomes invalid

<https://github.com/Cyfrin/2025-01-zaros-part-2/blob/35deb3e92b2a32cd304bf61d27e6071ef36e446d/src/market-making/branches/MarketMakingEngineConfigurationBranch.sol#L613C1-L654C6>

In configureFeeRecipient, recipients can only have their shares modified:

```solidity
function configureFeeRecipient(address feeRecipient, uint256 share) external onlyOwner {
    // Can set share to 0 but recipient remains in array
    marketMakingEngineConfiguration.protocolFeeRecipients.set(feeRecipient, share);
}
```

During reward distribution, transfers are attempted to all recipients regardless of share amount:

<https://github.com/Cyfrin/2025-01-zaros-part-2/blob/35deb3e92b2a32cd304bf61d27e6071ef36e446d/src/market-making/leaves/MarketMakingEngineConfiguration.sol#L69C1-L87C74>

```solidity
function distributeProtocolAssetReward(Data storage self, address asset, uint256 amount) internal {
    for (uint256 i; i < feeRecipientsLength; i++) {
        (address feeRecipient, uint256 shares) = self.protocolFeeRecipients.at(i);
        uint256 feeRecipientReward = amountX18.mul(ud60x18(shares))
            .div(totalFeeRecipientsSharesX18).intoUint256();

        // Transfer attempted even if shares or reward is 0
        // Will revert if recipient can't receive tokens
        IERC20(asset).safeTransfer(feeRecipient, feeRecipientReward);
    }
}
```

This is called in critical protocol functions:
fulfillSwap: Distributes swap fees
_convertAssetsToUsdc: Handles USDC conversions
sendWethToFeeRecipients: Distributes WETH rewards
If any recipient becomes invalid (blacklisted, reverts on transfer, etc.) or receives a zero-value transfer with a token that doesn't allow it and reverts, all reward distributions will fail
No way to remove problematic recipients
Gas inefficiency from iterating over and attempting transfers to zero-share recipients
Could completely block core protocol functions that depend on successful fee distribution

CreditDelegationBranch.rebalanceVaultsAssets doesn't take DEX swap slippage into consideration when swapping debt vault's collateral asset to credit vault's usdc.

CreditDelegationBranch.rebalanceVaultsAssets rebalances credit and debt between two vaults by swapping debt vault's collateral asset to USDC and accumulates this to credit vault's depositedUsdc and marketRealizedDebtUsd.

```solidity
uint256 assetInputNative = IDexAdapter(ctx.dexAdapter).getExpectedOutput(
    usdc,
    ctx.inDebtVaultCollateralAsset,
    Collateral.load(usdc).convertSd59x18ToTokenAmount(depositAmountUsdX18)
);

SwapExactInputSinglePayload memory swapCallData = SwapExactInputSinglePayload({
    tokenIn: ctx.inDebtVaultCollateralAsset,
    tokenOut: usdc,
    amountIn: assetInputNative,
    recipient: address(this)
});

IERC20(ctx.inDebtVaultCollateralAsset).approve(ctx.dexAdapter, assetInputNative);
dexSwapStrategy.executeSwapExactInputSingle(swapCallData); // <-- amountOut

uint128 usdDelta = depositAmountUsdX18.intoUint256().toUint128();

inCreditVault.depositedUsdc += usdDelta; // @audit usdDelta != amountOut
inCreditVault.marketsRealizedDebtUsd += usdDelta.toInt256().toInt128();
inDebtVault.depositedUsdc -= usdDelta;
inDebtVault.marketsRealizedDebtUsd -= usdDelta.toInt256().toInt128();
```

The problem is, this swapping is done via DEX like Curve, Uniswap V2/3 that uses CFMM to decide amountOut, while assetInputNative is estimated by price ratio.

So tokenOut will be different than usdDelta by up to slippageToleranceBps%

According to the current implementation, total sum of marketRealizedDebtUsd and total depositedUsdc remains the same after the rebalancing. Thus, slippage is not accounted anywhere.
The protocol will suffer from DEX swap slippage

Underflow in UsdTokenSwapConfig.getPremiumDiscountFactor will prevent users from swapping USD token to collateral when vault's credit / vaule ratio is above certain threshold.

Root Cause
UsdTokenSwapConfig.getPremiumDiscountFactor logic can be formalized in the following way:

$V$: vaultAssetsValueUsd

$D$: vaultDebtUsd

$x$: vaultDebtTvlRatioAbs

$f(x)$: premiumDiscountFactor

$x =  \left | \dfrac D V \right |$

$x^\prime = min(x, x_{max})$

$y = y{min} + \left ( y{max} - y{min} \right ) \left ( \dfrac {x^\prime - x{min}} {x{max} - x{min}} \right )^z$

$f(x) = \begin{cases} 
1 & \text {if }x < x_{min} 
\\
1 - y & \text {if } D < 0
\\
1 + y & \text{otherwise}
 \end{cases}$

!getPremiumDiscountFactor

According to the following comment:

```solidity
/// @dev The proposed initial curve is defined as:
///      f(x) = 1 + 9 * ((x - 0.3) / 0.5)^3
```

we can derive the following:
$y_{min} = 0$
$y_{max} = 9$
$x_{min} = 0.3$
$x_{max} = 0.8$

Thus, when $D < 0$ and $|D/V| > x_{min}$, 

$f(x) = 1 - y = 1 - (9 * \Delta x ^ 3) $

which will cause underflow in ud60x18 math for certain $\Delta x$

POC
```solidity
