+    uint128[] memory vaultIds = new uint128[](1);
+    vaultIds[0] = fuzzVaultConfig.vaultId;
+    uint128[] memory amountsIn = new uint128[](1);
+    amountsIn[0] = uint128(swapAmountX18.intoUint256());
