function _getSqrtPriceX96FromPool(IUniswapV3Pool _pool, uint32 _interval)
    public
    returns (uint160 _sqrtPriceX96)
{
    if (_interval == 0) {
        (_sqrtPriceX96,,,,,,) = _pool.slot0();
