    uint256 _totalAssetsAvailable = _totalAssetAvailable(totalAsset, _totalBorrow, true);
    if (_totalAssetsAvailable < _borrowAmount) {
        revert InsufficientAssetsInContract(_totalAssetsAvailable, _borrowAmount);
