        emit StratHarvest(msg.sender, wantHarvested, balanceOf());
    }
}

function addLiquidity() internal {
    uint256 outputBal = IERC20Upgradeable(output).balanceOf(address(this));
    uint256 lp0Amt = outputBal / 2;
    uint256 lp1Amt = outputBal - lp0Amt;
    ISolidlyRouter router = ISolidlyRouter(uniRouter);
    if (stable) {
        uint256 out0 = lp0Amt;
        if (lpToken0 != output) {
            out0 = (router.getAmountsOut(lp0Amt, outputToLp0Route)[outputToLp0Route.length - 1] * 1e18) / lp0Decimals;
        }
        uint256 out1 = lp1Amt;
        if (lpToken1 != output) {
            out1 = (router.getAmountsOut(lp1Amt, outputToLp1Route)[outputToLp1Route.length - 1] * 1e18) / lp1Decimals;
        }
        (uint256 amountA, uint256 amountB, ) = router.quoteAddLiquidity(
            lpToken0,
            lpToken1,
            stable,
            out0,
            out1
        );
        amountA = (amountA * 1e18) / lp0Decimals;
        amountB = (amountB * 1e18) / lp1Decimals;
        uint256 ratio = (((out0 * 1e18) / out1) * amountB) / amountA;
        lp0Amt = (outputBal * 1e18) / (ratio + 1e18);
        lp1Amt = outputBal - lp0Amt;
        if (lpToken0 != output) {
            router.swapExactTokensForTokens(
                lp0Amt,
                0,
                outputToLp0Route,
                address(this),
                block.timestamp
            );
        }
        if (lpToken1 != output) {
            router.swapExactTokensForTokens(
                lp1Amt,
                0,
                outputToLp1Route,
                address(this),
                block.timestamp
            );
        }
        uint256 lp0Bal = IERC20Upgradeable(lpToken0).balanceOf(address(this));
        uint256 lp1Bal = IERC20Upgradeable(lpToken1).balanceOf(address(this));
        router.addLiquidity(
            lpToken0,
            lpToken1,
            stable,
            lp0Bal,
            lp1Bal,
            address(this),
            block.timestamp
        );
    }
}
```
The KOL protocol has designed a new strategy contract to invest user deposits (held in KolStrategyThena), harvest growing yields, and collect any gains, if any, to the share holders. In the meantime, we notice the protocol takes a different approach by directly rewarding the yields back to investors. To elaborate, we show below the _harvest() function in KolStrategyThena. This routine essentially collects any pending rewards via gauge::getReward() (line 211) and then distributes the collected rewards evenly to current share holders. We notice the collected rewards are evenly distributed to share holders. With that, it is possible for a malicious actor to launch a flashloan-assisted deposit to claim the majority of rewards, resulting in significantly less rewards to legitimate share holders. This is possible as the harvest() may be triggered in a permissionless manner, allowing for a crafted contract to directly borrow a flashloan, deposit the borrowed loan into the vault pool, call harvest() to claim a majority share in rewards, and finally return the flashloan. In the meantime, the current protocol supports the conversion of output token to others as liquidity. Because of that, there is a constant need of swapping one asset to another. With that, the protocol has provided a helper routine addLiquidity(). To elaborate, we show above the helper routine. We notice the conversion is routed to Thena router in order to swap one asset to another. And the swap operation does not specify any restriction on possible slippage and is therefore vulnerable to possible front-running attacks, resulting in a smaller gain for this round of conversion. Note that this is a common issue plaguing current AMM-based DEX solutions. Specifically, a large trade may be sandwiched by a preceding sell to reduce the market price, and a tailgating buy-back of the same amount plus the trade amount. Such sandwiching behavior unfortunately causes a loss and brings a smaller return as expected to the trading user because the swap rate is lowered by the preceding sell. As a mitigation, we may consider specifying the restriction on possible slippage caused by the trade or referencing the TWAP or time-weighted average price of UniswapV2. Nevertheless, we need to acknowledge that this is largely inherent to current blockchain infrastructure and there is still a need to continue the search efforts for an effective defense.

To facilitate the reward distribution, the LayerBank protocol has a RewardController contract. It allows to lock the reward amount for a specified vestDuration. In the meantime, it also supports the early withdrawal of rewards, which may charge certain penalty if not expired. Our analysis shows the early withdrawal logic needs to be revisited. To elaborate, we show below the code snippet of the _ieeWithdrawableBalances() function. This function has a rather straightforward logic in locating the respective locked funds and compute the withdrawal amount as well as the penalty amount. We notice if the given unlockTime does not match any existing entry, the return value of index is not initialized and has the default value of 0, which may be mis-interpreted as the first entry. With that, we need to initialize the return value of index = uint256(-1) to avoid unnecessary mis-interpretation.
```solidity
function _ieeWithdrawableBalances(
    address user,
    uint256 unlockTime
) internal view returns(uint256 amount, uint256 penaltyAmount, uint256 burnAmount, uint256 index) {
    for(uint256 i = 0; i < userEarnings[user].length; i++) {
        if(userEarnings[user][i].unlockTime == unlockTime) {
            (amount, , penaltyAmount, burnAmount) = _penaltyInfo(userEarnings[user][i]);
            index = i;
            break;
        }
    }
}
```

Though there is a standardized ERC-20 specification, many token contracts may not strictly follow the specification or have additional functionalities beyond the specification. In this section, we examine the transfer() routine and possible idiosyncrasies from current widely-used token contracts. In particular, we use the popular stablecoin, i.e., USDT, as our example. We show the related code snippet below. Specifically, the transfer() routine does not have a return value defined and implemented. However, the IERC20 interface has defined the transfer() interface with a bool return value. As a result, the call to transfer() may expect a return value. With the lack of return value of USDT's transfer(), the call will be unfortunately reverted.
```solidity
function transfer(address _to, uint _value) public onlyPayloadSize(2 * 32) {
    uint fee = (_value.mul(basisPointsRate)).div(10000);
    if (fee > maximumFee) {
        fee = maximumFee;
    }
    uint sendAmount = _value.sub(fee);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(sendAmount);
    if (fee > 0) {
        balances[owner] = balances[owner].add(fee);
        Transfer(msg.sender, owner, fee);
    }
    Transfer(msg.sender, _to, sendAmount);
}
```
Because of that, a normal call to transfer() is suggested to use the safe version, i.e., safeTransfer(), In essence, it is a wrapper around ERC20 operations that may either throw on failure or return false without reverts. Moreover, the safe version also supports tokens that return no value (and instead revert or throw on failure). Note that non-reverting calls are assumed to be successful. In current implementation, if we examine the KratosTreasury::incurDebt() routine that is designed to allow approved addresses to borrow reserves. To accommodate the specific idiosyncrasy, there is a need to use safeTransfer(), instead of transfer() (line 398).
```solidity
function incurDebt(uint _amount, address _token) external {
    require(isDebtor[msg.sender], "Not approved");
    require(isReserveToken[_token], "Not accepted");
    uint value = valueOf(_token, _amount);
    uint maximumDebt = IERC20(MEMOries).balanceOf(msg.sender); // Can only borrow against sOHM held
    uint availableDebt = maximumDebt.sub(debtorBalance[msg.sender]);
    require(value <= availableDebt, "Exceeds debt limit");
    debtorBalance[msg.sender] = debtorBalance[msg.sender].add(value);
    totalDebt = totalDebt.add(value);
    totalReserves = totalReserves.sub(value);
    emit ReservesUpdated(totalReserves);
    IERC20(_token).transfer(msg.sender, _amount);
    emit CreateDebt(msg.sender, _token, _amount, value);
}
```

