    UserInfo storage user = userInfo[pid][msg.sender];
    // Effects
    user.rewardDebt = user.rewardDebt.sub(int256(amount.mul(pool.accRewardPerShare) / ACC_PAN_PRECISION));
    user.amount = user.amount.sub(amount);
