    all_assets[name].exist = false;
    emit RemoveAsset(name);
}

function add_asset(string memory name, address type_addr, bytes memory call_data) public onlyOwner{
    all_names.push(name);
    all_assets[name].exist = true;
    oracle.add_asset(name, type_addr, call_data);
    emit NewAsset(name, type_addr, call_data);
}
```
We emphasize that the privilege assignment may be necessary and consistent with the protocol design. However, it is worrisome if the privileged account is not governed by a DAO-like structure. Note that a compromised privileged account would allow the attacker to modify a number of sensitive system parameters, which directly undermines the assumption of the Plutos VirtualTrade design.

The ERC20Staking contract allows users to stake the supported target_token tokens and get in return lp_token tokens to represent the pool shares. While examining the share calculation with the given stakes, we notice an issue that may unnecessarily make the pool token extremely expensive and bring hurdles (or even causes loss) for later stakers. To elaborate, we show below the related code snippet of the ERC20Staking contract. The stake() routine is used for participating users to stake the supported asset and get respective lp_token in return. The issue occurs when the pool is being initialized under the assumption that the current pool is empty.
```solidity
function stake(uint256 _amount) public returns(uint256){
    uint256 amount = 0;
    uint256 prev = IERC20(target_token).balanceOf(address(this));
    IERC20(target_token).safeTransferFrom(msg.sender, address(this), _amount);
    amount = IERC20(target_token).balanceOf(address(this)).safeSub(prev);
    if(amount == 0){
        return 0;
    }
    uint256 lp_amount = 0;
    if(IERC20(lp_token).totalSupply() == 0){
        lp_amount = amount.safeMul(uint256(10) ** ERC20Base(lp_token).decimals()).safeDiv(uint256(10) ** ERC20Base(target_token).decimals());
    }else{
        uint256 t2 = IERC20(lp_token).totalSupply();
        lp_amount = amount.safeMul(t2).safeDiv(prev);
        if(lp_amount == 0){
            return 0;
        }
    }
    TokenInterface(lp_token).generateTokens(msg.sender, lp_amount);
    if(address(callback) != address(0x0)){
        callback.onStake(msg.sender, amount, lp_amount);
    }
    emit ERC20Stake(msg.sender, amount, lp_amount);
    return lp_amount;
}
```
Specifically, when the pool is being initialized, the lp_amount share value directly takes the value of amount (line 52), which is under control by the malicious actor. As this is the first stake, the current total supply equals the calculated lp_amount = amount.safeMul(uint256(10)**ERC20Base(lp_token).decimals()).safeDiv(uint256(10)**ERC20Base(target_token).decimals())= 1WEI. With that, the actor can further transfer a huge amount of target_token tokens to ERC20Staking contract with the goal of making the lp_token extremely expensive. An extremely expensive pool token can be very inconvenient to use as a small number of 1WEI may denote a large value. Furthermore, it can lead to precision issue in truncating the computed pool tokens for staked assets. If truncated to be zero, the staked assets are essentially considered dust and kept by the pool without returning any pool tokens. This is a known issue that has been mitigated in popular Uniswap. When providing the initial liquidity to the contract (i.e. when totalSupply is 0), the liquidity provider must sacrifice 1000 LP tokens (by sending them to address(0)). By doing so, we can ensure the granularity of the LP tokens is always at least 1000 and the malicious actor is not the sole holder. This approach may bring an additional cost for the initial liquidity provider, but this cost is expected to be low and acceptable.

The Pluz protocol has a core PluzAccountManager contract to oversee the account creation and management. In the process of examining the liquidation logic of an underwater position, we notice current implementation should be improved. In the following, we show the implementation of the related routine, i.e., liquidateCollateral(). This routine has a rather straightforward logic in repaying the debt from the calling user (a.k.a., liquidator) and seizing the collateral from the borrower being liquidated. It comes to our attention that the _lendAsset token is a rebasing one and the repayment funds are directly transferred from the liquidator in term of lendPoolActualAsset (line 271). With that, there is no need to unwrap the _lendAsset at all 1 (line 270). Moreover, this routine can also be improved to have the nonReentrant modifier to block unintended reentrancy attempts. Note other public functions from this PluzAccountManager contract have this nonReentrant modifier consistently applied.
```solidity
function liquidateCollateral(address account, uint256 debtToCover, address liquidationFeeTo) public {
    AccountLib.Health memory health = getAccountHealth(account);
    if (!health.isLiquidatable) revert Errors.AccountHealthy();
    // Mark account liquidatable if it isn't already.
    if (_accountLiquidationStartTime[account] == 0) {
        _accountLiquidationStartTime[account] = block.timestamp;
        emit AccountLiquidationStarted(account);
        this._afterLiquidationStarted(account);
    }
    // The collateral credited to the owner of the Account, not the Account itself.
    address accountOwner = _accountOwnerCache[account];
    uint256 debtAmount = getDebtAmount(account);
    AccountLib.CollateralLiquidation memory _result = _simulateCollateralLiquidation(accountOwner, debtAmount, debtToCover);
    // Transfer collateral to caller and their fee wallet
    _withdrawAssets(accountOwner, msg.sender, _result.collateralAmount - _result.bonusCollateral);
    _withdrawAssets(accountOwner, liquidationFeeTo, _result.bonusCollateral);
    // Transfer debt from sender to account.
    uint256 convertAmount = _convertAmount(_result.actualDebtToLiquidate, IERC20Rebasing(address(_lendAsset)));
    IERC20Rebasing(address(_lendAsset)).unwrap(_result.actualDebtToLiquidate);
    _lendPoolActualAsset.safeTransferFrom(msg.sender, account, convertAmount);
    IAccount(account).repay(_result.actualDebtToLiquidate);
    emit CollateralLiquidation(
        account, _result.collateralAmount, _result.bonusCollateral, _result.actualDebtToLiquidate);
}
```

The Pod vault has a key `modifyRewardToken()` function to modify the given token's reward configuration or add additional token amount for distribution. While reviewing its logic, we notice it can be improved by more thoroughly validating the given input arguments. To elaborate, we show below the implementation of this `modifyRewardToken()` routine. We notice the given argument of `_settings` is not properly validated and allows for an input with its `endTime` smaller than `startTime`. If such an incorrect setting is applied, it will revert every call to `_updatePod()` (Section 3.1).
```solidity
function modifyRewardToken(address token, uint256 amount, Settings calldata _settings) external nonReentrant checkOwnable {
    RewardToken storage _reward = rewards[token];
    if(! _reward.active) revert PodInvalidReward();
    uint256 _currentTimestamp = _currentBlockTimestamp();
    if (_currentTimestamp > _settings.endTime) {
        revert PodInvalidSettings();
    }
    Settings memory _validatedSettings = Settings({
        startTime: _settings.startTime,
        endTime: _settings.endTime
    });
    if(_reward.settings.endTime < _currentTimestamp) {
        if(_currentTimestamp > _settings.startTime) revert PodInvalidSettings();
        _reward.settings.startTime = _validatedSettings.startTime;
        _reward.accRewardsPerShare = 0;
        if(factory.feeOnAddReward() > 0) {
            uint256 fee = amount.mulDiv(factory.feeOnAddReward(), factory.FEE_BASIS());
            IERC20(token).transferFrom(msg.sender, factory.feeCollector(), fee);
            amount = amount - fee;
        }
    }
    if (token == asset()) {
        _rewardsInUnderlying = _rewardsInUnderlying + amount;
    }
    IERC20(token).transferFrom(msg.sender, address(this), amount);
    uint256 _newAmount = _reward.remainingAmount + amount;
    _reward.amount = _newAmount;
    _reward.remainingAmount = _newAmount;
    _reward.settings.endTime = _validatedSettings.endTime;
    _updatePod();
    emit ModifyReward(token, _newAmount, _reward.settings.startTime, _reward.settings.endTime);
}
```

The PRINT3R protocol has a core Market contract to maintain market-wide accounting. By design, it supports the trading of multiple assets under the same liquidity. In the process of analyzing the multi-asset support, we notice the new token addition logic can be improved. In the following, we show the implementation of the related routine, i.e., `addToken()`. As the name indicates, this routine is used to dynamically add a new token and accordingly support the share reallocation among supported tokens. However, it comes to our attention that the new token's pool is initialized (line 133) after the pool share reallocation (line 131). This is incorrect as the pool share allocation should be performed after the new token pool initialization.
```solidity
function addToken(
    MarketId _id,
    Pool.Config calldata _config,
    string memory _ticker,
    bytes calldata _newAllocations,
    bytes32 _priceRequestKey
) external onlyPoolOwner(_id) {
    Pool.GlobalState storage state = globalState[_id];
    if (!state.isMultiAsset) revert Market_SingleAssetMarket();
    if (state.assetIds.length() >= MAX_ASSETS) revert Market_MaxAssetsReached();
    bytes32 assetId = keccak256(abi.encode(_ticker));
    if (state.assetIds.contains(assetId)) revert Market_TokenAlreadyExists();
    Pool.validateConfig(_config);
    if (!state.assetIds.add(assetId)) revert Market_FailedToAddAssetId();
    state.tickers.push(_ticker);
    _reallocate(_id, _newAllocations, _priceRequestKey);
    Pool.initialize(marketStorage[_id][assetId], _config);
}
```

As mentioned earlier, the Market support in PRINT3R allows for the trading of multiple assets under the same liquidity. With that, the related oracle is required to dynamically add new token to query token prices. Our analysis shows the current oracle needs to be improved when adding a new token. In the following, we show the implementation of the related routine `supportAsset()`. For the new token, it basically maintains the correct mapping from the new token to the related pricing strategy (line 167). However, it forgets to maintain the related token decimals, i.e., `tokenDecimals[_ticker] = _tokenDecimals`. The lack of the new token's decimals will make the base unit of queried token price unavailable and possibly revert the oracle operation.
```solidity
function supportAsset(string memory _ticker, SecondaryStrategy calldata _strategy, uint8 _tokenDecimals) external onlyRoles(_ROLE_0) {
    bytes32 assetId = keccak256(abi.encode(_ticker));
    if (assetIds.contains(assetId)) return; // Return if already supported
    bool success = assetIds.add(assetId);
    if (!success) revert PriceFeed_AssetSupportFailed();
    strategies[_ticker] = _strategy;
    tokenDecimals[_ticker] = _tokenDecimals;
    emit AssetSupported(_ticker, _tokenDecimals);
}
```

