    s.buyWith = buyWith;
    s.toBuy = _toBuy;
    s.owner = msg.sender;
    s.iteration = _iteration;
    s.shares = 0;
    amountLeftInStream[count] = totalAmountAdjusted;
    list[msg.sender].push(count);
    // deposit to our contracts
    IERC20(buyWith).transferFrom(msg.sender, address(this), totalAmountAdjusted);
    if (streamYield[count]) {
        _depositToVault(count, totalAmountAdjusted, false);
    } else {
        sa.assetAmount = sa.assetAmount.add(totalAmountAdjusted);
    }
    allStreams.push(count);
    streamNature[count] = false;
}
```

In the meantime, we also suggest to use the safe-version of approve()/transfer()/transferFrom() in other related routines, including activate(), activateMultiple(), topUp(), and withdrawAsset().

