    require(amount1 <= getBalance(user, IERC20(token1)), "DepositOnLp: Insufficient token1 funds.");
    (uint256 amount0f, uint256 amount1f, uint256 lpRes) = _addLiquidity(token0, token1, amount0, amount1);
