contract UpliftOnlyExampleTest is BaseVaultTest {
     using CastingHelpers for address[];
     using ArrayHelpers for *;
@@ -1444,4 +1446,61 @@ contract UpliftOnlyExampleTest is BaseVaultTest {
         );
