Even if the argument isLastAttempt is set to false, the retryMessage() function cannot be called again.
According to the natspec comments on [232-233], the isLastAttempt argument of the function retryMessage() speciﬁes if it is the last attempt to retry the message. However, the status of the message is updated to FAILED or DONE independently of the value of the variable isLastAttempt. Then, after calling this function once, it cannot be called again, because the message status check on [250-252] would fail.
```solidity
function retryMessage(
    Message calldata message,
    bool isLastAttempt
) external nonReentrant whenNotPaused sameChain(message.destChainId) {
    // If the gasLimit is set to 0 or isLastAttempt is true, the caller must
    // be the message.owner.
    if (message.gasLimit == 0 || isLastAttempt) {
        if (msg.sender != message.owner) revert B_PERMISSION_DENIED();
    }
    bytes32 msgHash = hashMessage(message);
    if (messageStatus[msgHash] != Status.RETRIABLE) {
        revert B_NON_RETRIABLE();
    }
    // Attempt to invoke the messageCall.
    if (_invokeMessageCall(message, msgHash, gasleft())) {
        // Update the message status to "DONE" on successful invocation.
        _updateMessageStatus(msgHash, Status.DONE);
    } else {
        // Update the message status to "FAILED"
        _updateMessageStatus(msgHash, Status.FAILED); // @audit does not check `isLastAttempt'
    }
}
```

The withdrawal of funds from the Account contract is vulnerable to reentrancy.
function withdraw(uint256 amount, address market) external override {
    ITracer _tracer = ITracer(market);
    require(amount > 0, "ACT: Withdraw Amount");
    Types.AccountBalance storage userBalance = balances[market][msg.sender];
    require(
        marginIsValid(
            userBalance.base.sub(amount.toInt256()),
            userBalance.quote,
            pricing.fairPrices(market),
            userBalance.lastUpdatedGasPrice,
            market
        ),
        "ACT: Withdraw below valid Margin"
    );
    address tracerBaseToken = _tracer.tracerBaseToken();
    IERC20(tracerBaseToken).safeTransfer(msg.sender, amount);
    userBalance.base = userBalance.base.sub(amount.toInt256());
    userBalance.deposited = userBalance.deposited.sub(amount);
    int256 originalLeverage = userBalance.totalLeveragedValue;
    _updateAccountLeverage(userBalance.quote, pricing.fairPrices(market), userBalance.base, msg.sender, market, originalLeverage);
    // Safemath will throw if tvl[market] < amount
    tvl[market] = tvl[market].sub(amount);
    emit Withdraw(msg.sender, amount, market);
}
The above code is an excerpt of the function withdraw().
Here the check to ensure that the margin is valid (marginIsValid()) occurs before the funds are transferred to the user in IERC20(tracerBaseToken).safeTransfer(msg.sender, amount), which occurs before the balances are updated.
If a malicious user was able to gain control over the execution during IERC20(tracerBaseToken).safeTransfer(msg.sender, amount) then the user would be able to call withdraw() a second time.
This second call to withdraw() would occur before the users balances have been updated during the first iteration and so they will again pass the check isMarginValid(), even if the margin after both transfers would not be positive.
Thus, the call IERC20(tracerBaseToken).safeTransfer(msg.sender, amount) will be made again.
The user could then take control of the execution and call withdraw() a third time and then a fourth and so on until they have drained their entire userBalance.deposited after which there would be a subtraction underflow preventing further recursions.
Note that the likelihood of this vulnerability is low as the majority of ERC20 tokens do not render control of execution to arbitrary addresses during a call to transfer().

The withdrawal cooldown period for Backstop LPs is now configured using backstopLPConfig.withdrawCooldownDurationInSeconds, such that the withdrawal cooldown period is turned on when it is greater than 0 and turned off when it is equal 0.
However, the issue is that Backstop LPs can start the withdrawal timer before the withdrawal cooldown is turned on, allowing them to withdraw immediately even after the withdrawal cooldown is enabled.
1. Suppose the cooldown period for withdrawal has been disabled for a while, so withdrawCooldownDurationInSeconds == 0.
2. Knowing that the cooldown period will be enabled soon, Backstop LPs proceed to start the withdrawal timer using announceBackstopLpWithdraw().
3. Protocol now enables withdrawal cooldown to X seconds.
4. However, those Backstop LPs who had announced withdrawal earlier will be able to withdraw immediately as the withdrawal period is active.
```solidity
function announceBackstopLpWithdraw(Account.Data storage account) internal {
    CollateralPool.Data storage collateralPool = AccountCollateral.getPool(account.id);
    uint128 backstopLpAccountId = backstopLPConfig.accountId;
    if (backstopLpAccountId != account.id) {
        revert Errors.AccountIsNotBackstopLp(account.id, backstopLpAccountId, block.timestamp);
    }
    Timer.Data storage backstopLpWithdrawTimer = Timer.loadOrCreate(backstopLpTimerId(backstopLpAccountId));
    if (block.timestamp < backstopLpWithdrawTimer.startTimestamp) {
        revert Errors.BackstopLpCooldownPeriodAlreadyActive(backstopLpAccountId, backstopLpWithdrawTimer.startTimestamp, block.timestamp);
    }
    if (backstopLpWithdrawTimer.isActive()) {
        revert Errors.BackstopLpWithdrawPeriodAlreadyActive(backstopLpAccountId, block.timestamp);
    }
    backstopLpWithdrawTimer.schedule(
        block.timestamp,
        backstopLPConfig.withdrawCooldownDurationInSeconds,
        backstopLPConfig.withdrawDurationInSeconds
    );
}
```

There are three new storage variables (depthFactor, maxExposureFactor, maxPSlippage) in MarketConfigurationData that are used to perform slippage and exposure checks in Market.getPSlippage().
The issue is that these new storage variables will be initialized to zero for the existing Market as they were previously unused before this upgrade.
When maxExposureFactor == 0, it will cause getPSlippage() to incorrectly revert even when net exposure is valid.
```solidity
function getPSlippage(
    Data storage self,
    SD59x18 deltaBase,
    UD60x18 oraclePrice
) internal returns (SD59x18 pSlippage) {
    MarketConfigurationData memory marketConfig = getConfig(self);
    uint256 riskMatrixIndex = marketConfig.riskMatrixIndex;
    UD60x18 depthFactor = marketConfig.depthFactor;
    UD60x18 maxExposureFactor = marketConfig.maxExposureFactor;
    UD60x18 maxPSlippage = marketConfig.maxPSlippage;
    (
        UD60x18 maxExposureShort,
        UD60x18 maxExposureLong,
        SD59x18[] memory exposures
    ) = getPoolMaxExposures(self);
    SD59x18 deltaExposure = convertBaseToExposure(deltaBase, oraclePrice);
    SD59x18 netExposure = exposures[riskMatrixIndex].add(deltaExposure);
    UD60x18 maxExposure = netExposure.lt(ZERO_sd) ? maxExposureShort : maxExposureLong;
    // when maxExposureFactor == 0, this will revert for valid net exposure too
    if (netExposure.abs().intoUD60x18().gte(maxExposure.mul(maxExposureFactor))) {
        revert Errors.ExceededMaxExposure(netExposure, maxExposure);
    }
    pSlippage = computePSlippage({netExposure: netExposure, maxExposure: maxExposure, depthFactor: depthFactor});
    if (pSlippage.abs().intoUD60x18().gt(maxPSlippage)) {
        revert Errors.ExceededPSlippage(pSlippage, maxPSlippage);
    }
}
```

