    uint256 id = type(uint256).max; // set to max so an empty set doesn't return 0, the first index
    uint48 vesting;
    uint256 maxPayout;
    IBondAuctioneer auctioneer;
    for (uint256 i; i < len; ++i) {
        auctioneer = marketsToAuctioneers[ids[i]];
