function _payoutRewards() internal {
    if (block.timestamp < payoutLastPaid + rewardPeriod) return;
    uint48 numPeriods = (uint48(block.timestamp) - payoutLastPaid) / rewardPeriod;

    uint192 initRate = exchangeRate();
    uint256 payout;

