    315:         uint256 id,
    316:         uint256 quantity
    317:     ) public virtual can_buy(id) synchronized returns (bool) {
    318:         OfferInfo memory _offer = offers[id];
    319:         uint256 spend = mul(quantity, _offer.buy_amt) / _offer.pay_amt; // @audit should round up
    ...
    447:         return true;
    448:     }

