A member of the Security Council can be removed mid-term by calling `removeMember` in `SecurityCouncilManager.sol`. This can only be called by addresses that have the `MEMBER_REMOVER_ROLE` role; the `SecurityCouncilMemberRemovalGovernor.sol` contract and the 9 of 12 emergency Security Council:

```solidity
function removeMember(address _member) external onlyRole(MEMBER_REMOVER_ROLE) {
    if (_member == address(0)) {
        revert ZeroAddress();
    }
    Cohort cohort = _removeMemberFromCohortArray(_member);
    _scheduleUpdate();
    emit MemberRemoved({member: _member, cohort: cohort});
}
```

The actual member removal is performed by `_removeMemberFromCohortArray`:

```solidity
function _removeMemberFromCohortArray(address _member) internal returns (Cohort) {
    for (uint256 i = 0; i < 2; i++) {
        address[] storage cohort = i == 0 ? firstCohort : secondCohort;
        for (uint256 j = 0; j < cohort.length; j++) {
            if (_member == cohort[j]) {
                cohort[j] = cohort[cohort.length - 1];
                cohort.pop();
                return i == 0 ? Cohort.FIRST : Cohort.SECOND;
            }
        }
    }
    revert NotAMember({member: _member});
}
```

As you can see, the member that has been removed isn’t tracked/stored anywhere for later querying. So, let’s assume that the DAO has successfully voted to remove a member. The `removeMember` method is called when the vote is successful and the update is scheduled in the L2 timelock.

The Security Council now have the ability (as the only party with the `MEMBER_ADDER_ROLE` role) to add a new member to fill the relevant cohort on the council by calling `addMember`:

```solidity
function addMember(address _newMember, Cohort _cohort) external onlyRole(MEMBER_ADDER_ROLE) {
    _addMemberToCohortArray(_newMember, _cohort);
    _scheduleUpdate();
    emit MemberAdded(_newMember, _cohort);
}
```

Where `_addMemberToCohortArray` looks like:

```solidity
function _addMemberToCohortArray(address _newMember, Cohort _cohort) internal {
    if (_newMember == address(0)) {
        revert ZeroAddress();
    }
    address[] storage cohort = _cohort == Cohort.FIRST ? firstCohort : secondCohort;
    if (cohort.length == cohortSize) {
        revert CohortFull({cohort: _cohort});
    }
    if (firstCohortIncludes(_newMember)) {
        revert MemberInCohort({member: _newMember, cohort: Cohort.FIRST});
    }
    if (secondCohortIncludes(_newMember)) {
        revert MemberInCohort({member: _newMember, cohort: Cohort.SECOND});
    }

    cohort.push(_newMember);
}
```

As you can see, this method only checks to ensure the member being added doesn’t already exist in either cohort, however there is no validation whether or not this member has been removed before in the current term. As a result, any DAO votes to remove a member can be usurped by the Security Council since they can simply restate the member that was voted to be removed.

The Arbitrum DAO’s constitution outlines a careful process for replacing cohorts of Security Council members to avoid race conditions and operational conflicts, particularly during ongoing elections. However, the contract implementation lacks the necessary checks to ensure that cohort replacement aligns with ongoing governance activities.

The `replaceCohort` function is responsible for replacing a cohort with a new set of members. In this function, the old cohort is immediately deleted, and the new cohort is added. This process, while ensuring that only the new members are present in the cohort after replacement, does not account for potential ongoing elections or concurrent transactions.

```solidity
function replaceCohort(address[] memory _newCohort, Cohort _cohort)
    external
    onlyRole(COHORT_REPLACER_ROLE)
{
    if (_newCohort.length != cohortSize) {
        revert InvalidNewCohortLength({cohort: _newCohort, cohortSize: cohortSize});
    }

    // Delete the old cohort
    _cohort == Cohort.FIRST ? delete firstCohort : delete secondCohort;

    // Add members of the new cohort
    for (uint256 i = 0; i < _newCohort.length; i++) {
        _addMemberToCohortArray(_newCohort[i], _cohort);
    }

    _scheduleUpdate();
    emit CohortReplaced(_newCohort, _cohort);
}
```

The `owner` attribute of the `bonds` mapping is set on each `mint()`, but its value is never updated:

    // Array of bonds
    mapping(uint256 => Bond) public bonds;

    // Structure to store the bond information
    struct Bond {
      address owner; // @audit
      uint256 expiry;
      uint256 rdpxAmount;
    }

[RdpxDecayingBonds.sol#L36-L44](https://github.com/code-423n4/2023-08-dopex/blob/main/contracts/decaying-bonds/RdpxDecayingBonds.sol#L36-L44)

    function mint(
        address to,
        uint256 expiry,
        uint256 rdpxAmount
    ) external onlyRole(MINTER_ROLE) {
        _whenNotPaused();
        require(hasRole(MINTER_ROLE, msg.sender), "Caller is not a minter");
        uint256 bondId = _mintToken(to);
        bonds[bondId] = Bond(to, expiry, rdpxAmount); // @audit

        emit BondMinted(to, bondId, expiry, rdpxAmount);
    }

[RdpxDecayingBonds.sol#L122](https://github.com/code-423n4/2023-08-dopex/blob/main/contracts/decaying-bonds/RdpxDecayingBonds.sol#L122)

When a user bonds using rDPX directly they first call the `bond` function of the RdpxV2Core contract:

    function bond(
      uint256 _amount,
      uint256 rdpxBondId,
      address _to
    ) public returns (uint256 receiptTokenAmount) {
      _whenNotPaused();
      // Validate amount
      _validate(_amount > 0, 4);

      // Compute the bond cost
      (uint256 rdpxRequired, uint256 wethRequired) = calculateBondCost(
        _amount,
        rdpxBondId
      );
      ...
      // purchase options
      uint256 premium;
      if (putOptionsRequired) {
        premium = _purchaseOptions(rdpxRequired);
      }

      _transfer(rdpxRequired, wethRequired - premium, _amount, rdpxBondId);

      // Stake the ETH in the ReceiptToken contract
      receiptTokenAmount = _stake(_to, _amount);
      ...
    }

The amount of WETH required, `wethRequired`, is calculated by the `calculateBondCost` function with the main logic being the following (note: the cost of the premium for the purchased amount of rDPX PUT option coverage is also included in this amount, but i am not showing that code here):

    wethRequired =
      ((ETH_RATIO_PERCENTAGE - (bondDiscount / 2)) * _amount) /
      (DEFAULT_PRECISION * 1e2);

As can be seen, there is a potential `bondDiscount`, which can be at most 100e8. Given that ETH_RATIO_PERCENTAGE is set to 75e8, the minimum amount of `wethRequired` would be 25% of the `_amount` of dpxETH being minted. The remainder, which in this case would be 50% of the value of the dpxETH, will be provided by the reserve. Note: if this math didn’t make sense, recall that 75% of the value of the minted dpxETH needs to be provided in ETH, and this discount can be as much as 2/3 of the ETH amount, meaning the minimum ETH requirement of the user will be 75% * 2/3 = 25%.

The remainder of the ETH portion (`discountReceivedInWeth`) is then paid for by the reserve in the `_transfer` function, which is defined as follows:

    function _transfer(
      uint256 _rdpxAmount,
      uint256 _wethAmount,
      uint256 _bondAmount,
      uint256 _bondId
    ) internal {
      if (_bondId != 0) {
        ...
      } else {
        ...
        // calculate extra rdpx to withdraw to compensate for discount
        uint256 rdpxAmountInWeth = (_rdpxAmount * getRdpxPrice()) / 1e8;
        uint256 discountReceivedInWeth = _bondAmount -
          _wethAmount -
          rdpxAmountInWeth;
        uint256 extraRdpxToWithdraw = (discountReceivedInWeth * 1e8) /
          getRdpxPrice();

        // withdraw the rdpx
        IRdpxReserve(addresses.rdpxReserve).withdraw(
          _rdpxAmount + extraRdpxToWithdraw
        );

        reserveAsset[reservesIndex["RDPX"]].tokenBalance +=
          _rdpxAmount +
          extraRdpxToWithdraw;
      }
    }

As can be seen, the `discountReceivedInWeth`, which is an amount of ETH, will then be converted into an equivalent amount of rDPX (`extraRdpxToWithdraw`), and then this amount of rDPX is withdrawn to serve as the collateral for the minted rDPX.

The issue with this is the following call to `_stake` within the flow of the `bond` function, which has the following line of code:

    reserveAsset[reservesIndex["WETH"]].tokenBalance -= _amount / 2;

Essentially, irrespective of the actual amount of ETH which has been deposited by the user, for the specified `_amount` of dpxETH to mint, `_amount / 2` of ETH will be taken from the token reserves of the RdpxV2Core contract. This means that as more and more ETH discounts are given, this ETH amount will be drained to zero. At this point, future calls to `bond` will revert.

