= 3600;
uint32 PAYMENT_DEFAULT_SEC = 1;
vm.startPrank(address(marketOwner));
mReg.setPaymentCycle(marketId1, PaymentCycleType.Seconds, PAYMENT_CYCLE_SEC);
mReg.setPaymentDefaultDuration(marketId1, PAYMENT_DEFAULT_SEC);
