function testPOC(uint256 x) external pure {
    vm.assume(x < type(uint256).max / 1e18);
    vm.assume(x > 1e18);
    console2.log("(x / 1e18) * 1e18", (x / 1e18) * 1e18);
    console2.log("(x * 1e18) / 1e18", (x * 1e18) / 1e18);
}
