  uint cappedCr               = cr < 1e18 ? 1e18 : cr; /// == max(1e18, cr)
  uint liquidationEquityShare = (cappedCr - 1e18).mulWadDown(LIQUIDATION_REWARD); /// if cr<1, this is equal 0
  uint liquidationAssetShare  = (liquidationEquityShare + 1e18).divWadDown(cappedCr); /// if cr<1, this is equal 1e18

  uint numberOfVaults = vaults[id].length();
  for (uint i = 0; i < numberOfVaults; i++) {
      Vault vault      = Vault(vaults[id].at(i));
      uint  collateral = vault.id2asset(id).mulWadUp(liquidationAssetShare);
      vault.move(id, to, collateral);
  }
