        assertTrue(!size.getCreditPosition(CREDIT_POSITION_ID_START).forSale);

        // @audit-info however, alice can sell her `not for sale` credit position to candy
        vm.startPrank(alice);
        size.sellCreditMarket(
            SellCreditMarketParams({
                lender: candy,
