    for (uint256 i = 0; i < _strategies.length; ) {
        uint256 fractAmount = (amount * _weights[i]) / _totalWeight;
        if (fractAmount > 0) {
            totalDeployed += IStrategy(_strategies[i]).deploy(fractAmount);
